/* ============================================================
   HOLLOWMOOR — the valley remembers
   ============================================================ */
:root {
  --bone: #e9e1cf;
  --bone-dim: rgba(233, 225, 207, 0.55);
  --bone-faint: rgba(233, 225, 207, 0.28);
  --ink: #0b100e;
  --ink-2: #101713;
  --panel: rgba(12, 18, 15, 0.84);
  --panel-solid: #111814;
  --line: rgba(233, 225, 207, 0.14);
  --line-strong: rgba(233, 225, 207, 0.26);
  --ember: #e0763c;
  --ember-soft: #f0a064;
  --moss: #9aab72;
  --blood: #c94f43;
  --water: #7ba7ad;
  --gold: #d8b46a;
  --display: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: #070b09;
  color: var(--bone);
  font-family: var(--sans);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(120% 100% at 50% 10%, #18211a 0%, #0b100e 60%, #060907 100%);
}

canvas#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: none;
  touch-action: none;
}

.hidden { display: none !important; }
.muted { color: var(--bone-dim); }

button { font-family: inherit; color: inherit; }

kbd {
  font-family: var(--sans);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  padding: 2px 5px;
  border: 1px solid var(--line-strong);
  border-bottom-color: rgba(233, 225, 207, 0.12);
  border-radius: 3px;
  color: var(--bone-dim);
  background: rgba(233, 225, 207, 0.04);
}

/* ============================================================
   HUD
   ============================================================ */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  padding: 0;
}
#hud button, #hud .prompt { pointer-events: auto; }

.hud-top {
  position: absolute;
  top: calc(16px + var(--safe-top));
  left: calc(20px + var(--safe-left));
  right: calc(20px + var(--safe-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 180px;
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line-strong);
  border-radius: 3px;
  font-family: var(--display);
  font-size: 20px;
  color: var(--ember-soft);
  background: rgba(8, 12, 10, 0.55);
  box-shadow: inset 0 0 22px rgba(224, 118, 60, 0.08);
}
.brand-text { display: flex; flex-direction: column; gap: 3px; }
.brand-name {
  font-family: var(--display);
  font-size: 15px;
  letter-spacing: 0.24em;
  line-height: 1;
}
.brand-cycle {
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--bone-dim);
}

.objective {
  position: relative;
  padding: 8px 18px 9px;
  text-align: center;
  background: linear-gradient(180deg, rgba(10, 15, 12, 0.72), rgba(10, 15, 12, 0.34));
  border: 1px solid var(--line);
  border-radius: 4px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.25);
}
.obj-eyebrow {
  display: block;
  font-size: 8px;
  letter-spacing: 0.32em;
  color: var(--ember-soft);
  opacity: 0.85;
  margin-bottom: 4px;
}
.obj-row { display: flex; align-items: center; gap: 12px; }
#objText { font-family: var(--display); font-size: 14px; letter-spacing: 0.03em; }
.pips { display: flex; gap: 5px; }
.pips i {
  width: 8px; height: 8px;
  border: 1px solid var(--bone-faint);
  border-radius: 50%;
  transition: all .4s ease;
}
.pips i.on {
  background: var(--ember);
  border-color: var(--ember);
  box-shadow: 0 0 10px rgba(224, 118, 60, 0.8);
}

.clockbox {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
  padding-top: 2px;
  min-width: 130px;
}
.phase {
  font-size: 8px;
  letter-spacing: 0.3em;
  color: var(--bone-dim);
}
.phase.night { color: #8fa5d4; }
.phase.dusk { color: var(--ember-soft); }
.clock {
  font-family: var(--display);
  font-size: 15px;
  letter-spacing: 0.12em;
  color: var(--bone);
}

/* vitals */
.vitals {
  position: absolute;
  top: calc(70px + var(--safe-top));
  left: calc(22px + var(--safe-left));
  width: 222px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 10px 12px 11px;
  background: linear-gradient(180deg, rgba(9, 14, 11, 0.62), rgba(9, 14, 11, 0.28));
  border: 1px solid rgba(233, 225, 207, 0.09);
  border-radius: 4px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.vital { display: flex; align-items: center; gap: 9px; }
.vital-label {
  width: 48px;
  font-size: 7.5px;
  letter-spacing: 0.16em;
  color: var(--bone-dim);
  flex: none;
}
.bar {
  position: relative;
  flex: 1;
  height: 5px;
  background: rgba(233, 225, 207, 0.09);
  border-radius: 3px;
  overflow: hidden;
}
.fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  display: block;
  border-radius: 3px;
  transition: width .25s ease, background .3s ease;
}
.fill.health { background: linear-gradient(90deg, #9e3c33, #d76a56); box-shadow: 0 0 10px rgba(201, 79, 67, 0.4); }
.fill.stamina { background: linear-gradient(90deg, #8d7a3d, #d2b96a); }
.fill.hunger { background: linear-gradient(90deg, #8a6230, #c7914b); }
.fill.warmth { background: linear-gradient(90deg, #4b6c70, #86b3b9); }
.vital.low .bar { animation: lowPulse 1.1s ease-in-out infinite; }
@keyframes lowPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(201, 79, 67, 0); }
  50% { box-shadow: 0 0 0 2px rgba(201, 79, 67, 0.28); }
}

/* minimap */
.minimap-wrap {
  position: absolute;
  top: calc(70px + var(--safe-top));
  right: calc(22px + var(--safe-right));
  width: 186px;
  padding: 5px 5px 4px;
  background: rgba(9, 14, 11, 0.66);
  border: 1px solid var(--line);
  border-radius: 4px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
#minimap {
  display: block;
  width: 174px;
  height: 129px;
  border-radius: 2px;
  opacity: 0.92;
}
.minimap-label {
  display: block;
  padding: 4px 2px 1px;
  text-align: center;
  font-size: 7px;
  letter-spacing: 0.26em;
  color: var(--bone-faint);
}

/* learned ticker */
.learned {
  position: absolute;
  top: calc(232px + var(--safe-top));
  right: calc(22px + var(--safe-right));
  width: 232px;
  padding: 10px 11px 11px;
  background: linear-gradient(180deg, rgba(11, 16, 13, 0.6), rgba(11, 16, 13, 0.22));
  border-left: 1px solid var(--line);
  border-radius: 2px;
}
.learned-title {
  font-size: 7.5px;
  letter-spacing: 0.28em;
  color: var(--ember-soft);
  opacity: .9;
}
.learned-list { margin-top: 7px; display: flex; flex-direction: column; gap: 7px; }
.learned-empty { margin: 0; font-size: 11px; line-height: 1.45; color: var(--bone-dim); font-style: italic; }
.learned-item {
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 8px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--bone);
  animation: slideIn .5s cubic-bezier(.2,.8,.2,1);
}
.learned-item .glyph { color: var(--ember); font-size: 13px; line-height: 1.2; text-align: center; }
.learned-item .src { display: block; font-size: 8px; letter-spacing: .18em; color: var(--bone-faint); margin-top: 2px; }
@keyframes slideIn {
  from { opacity: 0; transform: translateX(10px); }
  to { opacity: 1; transform: translateX(0); }
}

/* resources */
.resources {
  position: absolute;
  left: calc(22px + var(--safe-left));
  bottom: calc(96px + var(--safe-bottom));
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  max-width: 360px;
}
.res {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 8px 0 6px;
  background: rgba(10, 15, 12, 0.68);
  border: 1px solid rgba(233, 225, 207, 0.1);
  border-radius: 3px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.res svg { width: 14px; height: 14px; opacity: .8; }
.res .amount { color: var(--bone); }
.res.empty { opacity: .42; }
.res.bump { animation: resBump .5s ease; }
@keyframes resBump { 0% { transform: scale(1); } 35% { transform: scale(1.12); } 100% { transform: scale(1); } }

/* hotbar */
.hotbar {
  position: absolute;
  left: 50%;
  bottom: calc(48px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  align-items: flex-end;
}
.slot {
  pointer-events: auto;
  position: relative;
  width: 50px;
  height: 50px;
  display: grid;
  place-items: center;
  background: rgba(9, 14, 11, 0.72);
  border: 1px solid rgba(233, 225, 207, 0.14);
  border-radius: 4px;
  color: var(--bone-dim);
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.slot svg { width: 24px; height: 24px; }
.slot:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.slot.active {
  border-color: rgba(224, 118, 60, 0.7);
  background: rgba(224, 118, 60, 0.13);
  color: var(--bone);
  box-shadow: 0 0 24px rgba(224, 118, 60, 0.14), inset 0 0 14px rgba(224, 118, 60, 0.08);
}
.slot .key {
  position: absolute;
  top: 3px;
  left: 5px;
  font-size: 7px;
  letter-spacing: .06em;
  color: var(--bone-faint);
}
.slot .count {
  position: absolute;
  right: 5px;
  bottom: 3px;
  font-size: 8px;
  color: var(--bone-dim);
  font-variant-numeric: tabular-nums;
}
.slot.ability { width: 42px; height: 46px; }
.slot.ability .label {
  font-size: 6.5px;
  letter-spacing: .12em;
  color: var(--bone-dim);
}
.slot.cooling::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(3, 6, 5, 0.55);
  border-radius: 3px;
}
.hotbar .divider { width: 1px; height: 34px; background: var(--line); align-self: center; margin: 0 2px; }

/* prompt */
.prompt {
  position: absolute;
  left: 50%;
  bottom: calc(122px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px 7px 8px;
  background: rgba(9, 14, 11, 0.8);
  border: 1px solid var(--line);
  border-radius: 3px;
  font-size: 11.5px;
  color: var(--bone);
  white-space: nowrap;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  animation: promptIn .2s ease;
}
.prompt kbd { color: var(--ember-soft); border-color: rgba(224,118,60,.4); }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 4px); } to { opacity: 1; transform: translate(-50%, 0); } }

/* side actions */
.side-actions {
  position: absolute;
  right: calc(22px + var(--safe-right));
  bottom: calc(48px + var(--safe-bottom));
  display: flex;
  gap: 6px;
}
.ghost-btn {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 11px;
  font-size: 9px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--bone-dim);
  background: rgba(9, 14, 11, 0.66);
  border: 1px solid var(--line);
  border-radius: 3px;
  cursor: pointer;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition: color .2s, border-color .2s, background .2s;
}
.ghost-btn:hover { color: var(--bone); border-color: var(--line-strong); background: rgba(20, 28, 22, 0.8); }
.ghost-btn kbd { font-size: 7px; padding: 1px 3px; }

.controls-hint {
  position: absolute;
  left: 50%;
  bottom: calc(20px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  gap: 14px;
  font-size: 9px;
  color: rgba(233, 225, 207, 0.3);
  letter-spacing: .04em;
  white-space: nowrap;
  transition: opacity 1.4s ease;
}
.controls-hint b { color: rgba(233, 225, 207, 0.55); font-weight: 600; }
.controls-hint.fade { opacity: 0; }

/* toasts */
.toasts {
  position: absolute;
  top: calc(96px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: min(520px, 80vw);
  pointer-events: none;
}
.toast {
  padding: 8px 14px;
  font-size: 11.5px;
  letter-spacing: .02em;
  text-align: center;
  color: var(--bone);
  background: rgba(8, 13, 10, 0.86);
  border: 1px solid rgba(233, 225, 207, 0.14);
  border-radius: 3px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  animation: toastIn .4s cubic-bezier(.2,.8,.2,1);
  line-height: 1.35;
}
.toast.danger { border-color: rgba(201, 79, 67, 0.5); color: #f0b8b0; }
.toast.learn { border-color: rgba(224, 118, 60, 0.55); color: var(--ember-soft); }
.toast.good { border-color: rgba(154, 171, 114, 0.45); color: #c8d5a5; }
.toast.out { animation: toastOut .5s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

.tool-chip {
  position: absolute;
  right: calc(30px + var(--safe-right));
  bottom: calc(196px + var(--safe-bottom));
  padding: 5px 10px;
  font-size: 8px;
  letter-spacing: .18em;
  color: var(--bone-dim);
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(9, 14, 11, 0.7);
}

/* ============================================================
   TITLE
   ============================================================ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(24px + var(--safe-top)) 24px calc(24px + var(--safe-bottom));
}

.title-screen {
  background:
    radial-gradient(90% 70% at 50% 45%, rgba(18, 28, 21, 0.18) 0%, rgba(6, 10, 8, 0.72) 62%, rgba(4, 7, 5, 0.94) 100%);
  overflow: hidden;
  z-index: 50;
}
.title-vignette {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(6, 10, 8, 0.65) 0%, rgba(6, 10, 8, 0) 30%, rgba(6, 10, 8, 0) 68%, rgba(4, 7, 5, 0.9) 100%);
  pointer-events: none;
}
.title-inner {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 780px;
  padding-bottom: 40px;
  animation: titleRise 1.4s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes titleRise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}
.eyebrow {
  margin: 0;
  font-size: 8.5px;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--ember-soft);
  opacity: .92;
}
.title-inner h1 {
  margin: 14px 0 6px;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(64px, 11.4vw, 148px);
  line-height: .92;
  letter-spacing: 0.045em;
  color: #f2ead6;
  text-shadow: 0 2px 0 rgba(0,0,0,.28), 0 22px 70px rgba(0, 0, 0, 0.55);
}
.title-rule {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: min(360px, 70%);
  margin: 20px auto 18px;
  color: var(--ember);
}
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(233,225,207,.25)); }
.title-rule i:last-child { background: linear-gradient(90deg, rgba(233,225,207,.25), transparent); }
.title-rule span { font-size: 10px; color: var(--ember-soft); }
.tagline {
  margin: 0 auto;
  max-width: 440px;
  font-family: var(--display);
  font-size: clamp(14px, 1.5vw, 18px);
  line-height: 1.6;
  font-style: italic;
  color: rgba(233, 225, 207, 0.68);
}
.play-btn {
  margin-top: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-width: 168px;
  height: 50px;
  padding: 0 24px;
  font-size: 11px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #1a120c;
  background: linear-gradient(180deg, #f0b37a, #e0763c);
  border: 1px solid rgba(255, 210, 160, 0.5);
  border-radius: 3px;
  cursor: pointer;
  box-shadow: 0 14px 40px rgba(224, 118, 60, 0.22), inset 0 1px 0 rgba(255,255,255,.35);
  transition: transform .2s ease, box-shadow .2s ease, filter .2s ease;
}
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.05); box-shadow: 0 18px 50px rgba(224, 118, 60, 0.3); }
.play-btn:active { transform: translateY(0); }
.play-btn svg { width: 15px; height: 15px; }
.play-btn.small { margin-top: 22px; min-width: 210px; height: 46px; font-size: 10px; }

.title-hint {
  margin: 18px 0 0;
  font-size: 9.5px;
  letter-spacing: .06em;
  color: rgba(233, 225, 207, 0.38);
}
.title-hint b { color: rgba(233, 225, 207, 0.7); }
.title-cycle {
  margin: 32px 0 0;
  font-size: 8px;
  letter-spacing: 0.3em;
  color: rgba(233, 225, 207, 0.32);
}
.title-foot {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(18px + var(--safe-bottom));
  display: flex;
  justify-content: space-between;
  padding: 0 calc(28px + var(--safe-left)) 0 calc(28px + var(--safe-right));
  font-size: 7px;
  letter-spacing: 0.28em;
  color: rgba(233, 225, 207, 0.24);
  z-index: 3;
}

/* ============================================================
   PANELS — ledger & craft
   ============================================================ */
.panel-screen {
  background: rgba(4, 8, 6, 0.66);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  z-index: 60;
}
.ledger-panel, .craft-panel {
  position: relative;
  width: min(1080px, 94vw);
  max-height: min(84vh, 780px);
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(120% 100% at 20% 0%, rgba(32, 42, 32, 0.55), transparent 60%),
    linear-gradient(180deg, rgba(16, 23, 18, 0.97), rgba(9, 14, 11, 0.98));
  border: 1px solid rgba(233, 225, 207, 0.16);
  border-radius: 5px;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6);
  animation: panelIn .35s cubic-bezier(.2,.8,.2,1);
}
.craft-panel { width: min(720px, 94vw); }
@keyframes panelIn { from { opacity: 0; transform: translateY(10px) scale(.995); } to { opacity: 1; transform: none; } }
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 22px 26px 18px;
  border-bottom: 1px solid rgba(233, 225, 207, 0.1);
}
.panel-head h2 {
  margin: 5px 0 0;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(28px, 3.4vw, 42px);
  letter-spacing: .02em;
  line-height: 1;
}
.close-btn {
  width: 38px;
  height: 30px;
  font-size: 8px;
  letter-spacing: .14em;
  color: var(--bone-dim);
  background: rgba(233, 225, 207, 0.04);
  border: 1px solid var(--line);
  border-radius: 3px;
  cursor: pointer;
}
.close-btn:hover { color: var(--bone); border-color: var(--line-strong); }

.ledger-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 0;
  min-height: 0;
  flex: 1;
  overflow: hidden;
}
.ledger-left, .ledger-right {
  padding: 18px 24px 20px;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.ledger-left { border-right: 1px solid rgba(233, 225, 207, 0.09); }
.panel-subhead {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-bottom: 9px;
  margin-bottom: 4px;
  font-size: 8px;
  letter-spacing: 0.26em;
  color: var(--bone-dim);
  border-bottom: 1px solid rgba(233, 225, 207, 0.08);
}
.ledger-events {
  overflow-y: auto;
  padding-right: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(233,225,207,.16) transparent;
}
.ledger-events::-webkit-scrollbar { width: 4px; }
.ledger-events::-webkit-scrollbar-thumb { background: rgba(233,225,207,.16); border-radius: 4px; }
.event {
  display: grid;
  grid-template-columns: 44px 22px 1fr;
  gap: 8px;
  align-items: start;
  padding: 9px 4px;
  border-bottom: 1px solid rgba(233, 225, 207, 0.05);
  font-size: 12px;
  line-height: 1.45;
  color: rgba(233, 225, 207, 0.82);
  animation: fadeIn .3s ease;
}
.event .stamp {
  font-size: 8px;
  letter-spacing: .06em;
  color: var(--bone-faint);
  padding-top: 3px;
  white-space: nowrap;
}
.event .eicon { color: var(--ember-soft); text-align: center; font-size: 13px; line-height: 1.2; }
.event.fresh { background: rgba(224, 118, 60, 0.05); }
.event .tagline { display: block; font-size: 8px; letter-spacing: .16em; color: var(--bone-faint); margin-top: 3px; text-transform: uppercase; }
.empty-note { padding: 22px 4px; font-size: 12px; font-style: italic; color: var(--bone-dim); line-height: 1.6; }

.adapt-list { display: flex; flex-direction: column; gap: 6px; overflow-y: auto; padding: 4px 4px 4px 0; scrollbar-width: thin; }
.adapt {
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 10px;
  padding: 9px 10px;
  border: 1px solid rgba(233, 225, 207, 0.07);
  border-radius: 3px;
  background: rgba(233, 225, 207, 0.015);
}
.adapt .glyph {
  width: 30px; height: 30px;
  display: grid; place-items: center;
  font-size: 15px;
  color: var(--bone-faint);
  border: 1px solid rgba(233, 225, 207, 0.12);
  border-radius: 50%;
}
.adapt h4 { margin: 0 0 2px; font-family: var(--display); font-weight: 400; font-size: 13.5px; letter-spacing: .02em; color: var(--bone-dim); }
.adapt p { margin: 0; font-size: 10.5px; line-height: 1.45; color: var(--bone-faint); }
.adapt.on { border-color: rgba(224, 118, 60, 0.32); background: rgba(224, 118, 60, 0.06); }
.adapt.on .glyph { color: var(--ember-soft); border-color: rgba(224, 118, 60, 0.42); box-shadow: 0 0 16px rgba(224,118,60,.12); }
.adapt.on h4 { color: var(--bone); }
.adapt.on p { color: var(--bone-dim); }
.trait-subhead { margin-top: 14px; }
.trait-list { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
.trait-row { display: grid; grid-template-columns: 60px 1fr 24px; gap: 8px; align-items: center; font-size: 8px; letter-spacing: .14em; color: var(--bone-dim); }
.trait-track { height: 4px; background: rgba(233, 225, 207, 0.08); border-radius: 2px; overflow: hidden; }
.trait-track i { display: block; height: 100%; background: linear-gradient(90deg, #6d7d52, var(--moss)); border-radius: 2px; }
.trait-row span:last-child { text-align: right; font-variant-numeric: tabular-nums; color: var(--bone-faint); }
.panel-foot {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 26px;
  border-top: 1px solid rgba(233, 225, 207, 0.09);
  font-size: 9.5px;
  color: var(--bone-dim);
}
.panel-foot b { color: var(--bone); font-weight: 600; }

/* craft */
.recipe-list {
  padding: 12px 18px 18px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 7px;
  scrollbar-width: thin;
}
.recipe {
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 10px 12px;
  border: 1px solid rgba(233, 225, 207, 0.08);
  border-radius: 3px;
  background: rgba(233, 225, 207, 0.015);
}
.recipe .r-icon {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  color: var(--bone-dim);
  background: rgba(233, 225, 207, 0.04);
  border: 1px solid rgba(233, 225, 207, 0.08);
  border-radius: 3px;
}
.recipe .r-icon svg { width: 20px; height: 20px; }
.recipe h4 { margin: 0 0 3px; font-family: var(--display); font-weight: 400; font-size: 14px; }
.recipe .r-desc { font-size: 10px; color: var(--bone-dim); line-height: 1.4; }
.recipe .cost { display: flex; gap: 6px; margin-top: 5px; flex-wrap: wrap; }
.cost-chip { display: inline-flex; align-items: center; gap: 3px; font-size: 9px; color: var(--bone-dim); padding: 2px 5px; border: 1px solid rgba(233,225,207,.1); border-radius: 2px; }
.cost-chip.lack { color: rgba(201,79,67,.85); border-color: rgba(201,79,67,.24); }
.cost-chip svg { width: 10px; height: 10px; }
.craft-btn {
  min-width: 74px;
  height: 30px;
  padding: 0 12px;
  font-size: 8.5px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--bone);
  background: rgba(224, 118, 60, 0.12);
  border: 1px solid rgba(224, 118, 60, 0.4);
  border-radius: 3px;
  cursor: pointer;
  transition: background .2s, border-color .2s;
}
.craft-btn:hover:not(:disabled) { background: rgba(224, 118, 60, 0.22); border-color: rgba(224, 118, 60, 0.7); }
.craft-btn:disabled { color: var(--bone-faint); border-color: rgba(233,225,207,.1); background: transparent; cursor: default; }
.recipe.owned .craft-btn { border-color: rgba(154, 171, 114, 0.25); background: transparent; color: var(--bone-faint); }

/* ============================================================
   DIALOGUE
   ============================================================ */
.dialogue {
  position: absolute;
  left: 50%;
  bottom: calc(96px + var(--safe-bottom));
  transform: translateX(-50%);
  z-index: 30;
  width: min(720px, calc(100vw - 32px));
  display: grid;
  grid-template-columns: 68px 1fr;
  gap: 14px;
  padding: 14px;
  background:
    linear-gradient(180deg, rgba(16, 23, 18, 0.97), rgba(10, 15, 12, 0.98));
  border: 1px solid rgba(233, 225, 207, 0.18);
  border-radius: 5px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
  animation: dialogueIn .3s cubic-bezier(.2,.8,.2,1);
}
@keyframes dialogueIn { from { opacity: 0; transform: translate(-50%, 10px); } to { opacity: 1; transform: translate(-50%, 0); } }
.portrait {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--display);
  font-size: 24px;
  color: #1a120c;
  background: radial-gradient(circle at 35% 30%, #cbb98e, #8b7854);
  border: 1px solid rgba(233, 225, 207, 0.2);
  box-shadow: inset 0 0 20px rgba(0,0,0,.18);
}
.dialogue-body { min-width: 0; }
.dialogue-head { display: flex; align-items: baseline; gap: 9px; margin-bottom: 5px; }
.dialogue-head #dialogueName { font-family: var(--display); font-size: 16px; letter-spacing: .03em; }
.dialogue-head #dialogueRole { font-size: 8px; letter-spacing: .2em; text-transform: uppercase; }
