    case 'snare': return '⌖';
    case 'flame': return '✹';
    case 'mercy': return '✦';
    case 'greed': return '◈';
    case 'death': return '☠';
    case 'build': return '⌂';
    case 'explore': return '◎';
    case 'gather': return '❧';
    case 'cairn': return '△';
    case 'arrive': return '◇';
    case 'sleep': return '☾';
    case 'save': return '✧';
    default: return '·';
