import { clamp, dist, TAU, angleLerp } from './util.js';
import { resolveCollisions, hasLineOfSight } from './world.js';
import { TOOLS } from './config.js';

const angleDelta = (a, b) => Math.atan2(Math.sin(b - a), Math.cos(b - a));

export function enemyCap(game) {
  const mods = game.chronicle.mods();
  const night = game.nightLevel();
  return Math.min(9, 3 + Math.floor(night * 2) + mods.extra + Math.min(2, Math.floor(game.time.day / 4)));
}

/* ============================================================
   PLAYER ACTIONS
   ============================================================ */
export function attack(game) {
  const p = game.player;
  if (game.mode !== 'play' || p.dead || p.atkCd > 0) return;
  const tool = TOOLS[p.tool];
  if (p.stamina < tool.stamina) {
    game.ui.toast('Too winded. Give it a breath.', 'danger', 1500);
    return;
  }
  if (!tool.melee && p.arrows <= 0) {
    game.ui.toast('Your quiver is empty. Whittle arrows in the craft panel.', 'danger', 2600);
    return;
  }

  p.atkCd = tool.cd;
  p.stamina = Math.max(0, p.stamina - tool.stamina);
  p.atkAnim = 0.24;
  p.swingAngle = p.angle;
  game.audio.sfx(tool.melee ? 'swing' : 'bow');

  if (!tool.melee) {
    p.arrows -= 1;
    const speed = 860;
    game.projectiles.push({
      x: p.x + Math.cos(p.angle) * 22,
      y: p.y + Math.sin(p.angle) * 22 - 4,
      vx: Math.cos(p.angle) * speed,
      vy: Math.sin(p.angle) * speed,
      life: 1.4, angle: p.angle, from: 'player', dmg: tool.dmg
    });
    game.addParticles('spark', p.x + Math.cos(p.angle) * 20, p.y + Math.sin(p.angle) * 20, 2, { color: '#d8c9a2' });
    if (game.ui) game.ui.updateResources(game);
    return;
  }

  const reach = tool.range;
  let hits = 0;
  for (const e of game.enemies) {
    if (e.dead || e.fade) continue;
    const d = dist(p.x, p.y, e.x, e.y);
    if (d > reach + e.r + 4) continue;
    if (Math.abs(angleDelta(p.angle, Math.atan2(e.y - p.y, e.x - p.x))) > tool.arc / 2) continue;
    const crit = p.sneak && !e.aggro;
    const dmg = tool.dmg * (crit ? 2.25 : 1) * (0.92 + game.rng.next() * 0.16);
    damageEnemy(game, e, dmg, 'melee', crit);
    hits++;
  }
  for (const a of [...game.animals]) {
    const d = dist(p.x, p.y, a.x, a.y);
    if (d > reach + 14) continue;
    if (Math.abs(angleDelta(p.angle, Math.atan2(a.y - p.y, a.x - p.x))) > tool.arc / 2) continue;
    a.hp -= tool.dmg;
    a.hit = 0.2;
    game.addParticles('blood', a.x, a.y, 6, {});
    game.addFloat(`-${Math.round(tool.dmg)}`, a.x, a.y - 18, '#d8c9a2', 11);
    game.audio.sfx('hit');
    if (a.hp <= 0) game.killAnimal(a);
  }
  for (const t of [...game.traps]) {
    if (!t.armed) continue;
    if (dist(p.x, p.y, t.x, t.y) < reach + 12) {
      t.armed = false;
      game.traps = game.traps.filter(x => x !== t);
      p.traps += 1;
      game.addFloat('+1 snare', t.x, t.y - 10, '#c9b98d', 10);
    }
  }

  // chop / mine the nearest prop in the swing
  let prop = null, pd = Infinity;
  for (const pr of game.world.props) {
    if (pr.done) continue;
    if (!['pine', 'oak', 'dead', 'rock'].includes(pr.kind)) continue;
    const d = dist(p.x, p.y, pr.x, pr.y);
    if (d > reach + (pr.r || 14) + 18 || d > pd) continue;
    if (Math.abs(angleDelta(p.angle, Math.atan2(pr.y - p.y, pr.x - p.x))) > 1.2) continue;
    prop = pr;
    pd = d;
  }
  if (prop) {
    hitProp(game, prop, tool);
    hits++;
  }

  if (hits === 0) {
    const tx = p.x + Math.cos(p.angle) * reach * 0.65;
    const ty = p.y + Math.sin(p.angle) * reach * 0.65;
    game.addParticles('dust', tx, ty, 2, { color: '#8d886c' });
  }
  if (game.ui) game.ui.updateResources(game);
}

function hitProp(game, prop, tool) {
  const p = game.player;
  const isRock = prop.kind === 'rock';
  const dmg = isRock ? 1 : (tool.id === 'axe' ? 1.15 : 0.7);
  prop.hp -= dmg;
  if (isRock) {
    p.stone += 1;
    game.addParticles('stone', prop.x, prop.y, 5, {});
    game.audio.sfx('hit');
    game.addFloat('+1 stone', prop.x, prop.y - 14, '#b9b9ad', 10);
    if (prop.hp <= 0) {
      prop.done = true;
      p.stone += 2;
      game.addParticles('dust', prop.x, prop.y, 10, { color: '#8a8a80' });
      game.addFloat('+2 stone', prop.x, prop.y - 20, '#b9b9ad', 11);
      game.record({
        kind: 'gather', text: `You broke stone apart in ${game.locationName()}.`,
        traits: { foraged: 1 }, x: prop.x, y: prop.y
      });
    }
  } else {
    game.addParticles('leaf', prop.x, prop.y - 20, 7, { color: prop.kind === 'dead' ? '#6f6252' : '#74834f' });
    game.audio.sfx('hit');
    if (prop.hp <= 0) {
      prop.done = true;
      const wood = prop.kind === 'oak' ? 5 : prop.kind === 'dead' ? 2 : 4;
      p.wood += wood;
      game.addFloat(`+${wood} wood`, prop.x, prop.y - 18, '#c9b98d', 11);
      game.addParticles('dust', prop.x, prop.y, 12, { color: '#766a4f' });
      game.record({
        kind: 'gather',
        text: prop.kind === 'dead'
          ? `You pulled down a dead tree in ${game.locationName()}.`
          : `You felled a ${prop.kind === 'oak' ? 'broad oak' : 'pine'} in ${game.locationName()}.`,
        traits: { foraged: 1 }, x: prop.x, y: prop.y
      });
    } else {
      game.addFloat('chop', prop.x, prop.y - 22, '#c9b98d', 9);
    }
  }
  if (game.ui) game.ui.updateResources(game);
}

export function dodge(game) {
  const p = game.player;
  if (game.mode !== 'play' || p.dead || p.dashCd > 0 || p.stamina < 20) return;
  let mx = 0, my = 0;
  if (game.keys.has('KeyA') || game.keys.has('ArrowLeft')) mx -= 1;
  if (game.keys.has('KeyD') || game.keys.has('ArrowRight')) mx += 1;
  if (game.keys.has('KeyW') || game.keys.has('ArrowUp')) my -= 1;
  if (game.keys.has('KeyS') || game.keys.has('ArrowDown')) my += 1;
  mx += game.stick.x;
  my += game.stick.y;
  if (Math.hypot(mx, my) < 0.2) {
    mx = -Math.cos(p.angle);
    my = -Math.sin(p.angle);
  }
  const m = Math.hypot(mx, my) || 1;
  p.dashT = 0.2;
  p.dashX = (mx / m) * 660;
  p.dashY = (my / m) * 660;
  p.dashCd = 1.05;
  p.stamina = Math.max(0, p.stamina - 20);
  p.invuln = Math.max(p.invuln, 0.4);
  game.audio.sfx('swing');
  game.addParticles('dust', p.x, p.y + 8, 7, { color: '#a49a76' });
  const near = game.enemies.some(e => !e.dead && !e.fade && dist(e.x, e.y, p.x, p.y) < 210);
  if (near && game.t - p.lastEvade > 2) {
    p.lastEvade = game.t;
    game.addFloat('EVADE', p.x, p.y - 34, '#a9b77c', 11);
    game.record({
      kind: 'shadow', text: 'You slipped out of a Hollowed’s reach.',
      traits: { escapes: 1 }, x: p.x, y: p.y
    });
  }
  if (game.ui) game.ui.updateResources(game);
}

export function ember(game) {
  const p = game.player;
  if (game.mode !== 'play' || p.dead || p.emberCd > 0) return;
  if (p.stamina < 16) {
    game.ui.toast('Not enough breath to wave fire.', 'danger', 1400);
    return;
  }
  p.emberCd = 6;
  p.stamina -= 16;
  game.emberRing = { x: p.x, y: p.y, t: 0.7, max: 0.7 };
  game.audio.sfx('ember');
  game.shake = Math.max(game.shake, 0.25);
  for (let i = 0; i < 20; i++) {
    const a = (i / 20) * TAU;
    game.addParticles('spark', p.x + Math.cos(a) * 18, p.y + Math.sin(a) * 18, 1, {
      color: '#f0a064', speed: 120, life: 0.5
    });
  }
  const mods = game.chronicle.mods();
  for (const e of game.enemies) {
    if (e.dead || e.fade) continue;
    const d = dist(p.x, p.y, e.x, e.y);
    if (d > 178) continue;
    if (mods.fireResist) {
      damageEnemy(game, e, 5, 'ember');
    } else {
      e.fear = Math.max(e.fear, 3.2);
      e.aggro = false;
      e.windup = 0;
      damageEnemy(game, e, 11, 'ember');
      game.addFloat('FEARED', e.x, e.y - 28, '#e0a05c', 10);
    }
  }
  game.record({
    kind: 'flame', text: 'You waved fire at the dark. The dark took notes.',
    traits: { flame: 1 }, x: p.x, y: p.y
  });
  if (game.ui) game.ui.updateResources(game);
}

export function placeTrap(game) {
  const p = game.player;
  if (game.mode !== 'play' || p.dead) return;
  if (p.traps <= 0) {
    game.ui.toast('No snares left. Twist more from fibre.', 'danger', 2000);
    return;
  }
  p.traps -= 1;
  game.traps.push({
    x: p.x + Math.cos(p.angle) * 26,
    y: p.y + Math.sin(p.angle) * 26,
    armed: true,
    uid: `${Date.now().toString(36)}-${game.rng.int(0, 99999)}`,
    seed: game.rng.range(0, 1000)
  });
  game.audio.sfx('ui');
  game.addParticles('dust', p.x, p.y, 4, {});
  game.addFloat('snare set', p.x, p.y - 24, '#c9b98d', 10);
  if (game.ui) game.ui.updateResources(game);
}

/* ============================================================
   ENEMIES
   ============================================================ */
export function spawnEnemy(game, opts = {}) {
  const mods = game.chronicle.mods();
  const night = game.nightLevel();
  const p = game.player;
  let x = opts.x, y = opts.y;
  if (x == null || y == null) {
    let placed = false;
    for (let i = 0; i < 40; i++) {
      const a = game.rng.range(0, TAU);
      const r = game.rng.range(620, 900);
      const tx = p.x + Math.cos(a) * r;
      const ty = p.y + Math.sin(a) * r;
      if (tx < 80 || ty < 80 || tx > game.world.w - 80 || ty > game.world.h - 80) continue;
      if (game.world.waterAt(tx, ty)) continue;
      if (dist(tx, ty, game.world.village.x, game.world.village.y) < 430) continue;
      x = tx; y = ty;
      placed = true;
      break;
    }
    if (!placed) {
      x = clamp(p.x + 650, 100, game.world.w - 100);
      y = clamp(p.y + 650, 100, game.world.h - 100);
    }
  }
  const archer = !!mods.archers && game.rng.chance(0.3);
  const hp = (archer ? 38 : 48) + night * 14 + Math.min(22, game.time.day * 2);
  const e = {
    x, y, spawnX: x, spawnY: y,
    wanderX: x, wanderY: y,
    r: archer ? 13 : 15,
    angle: game.rng.range(0, TAU),
    hp, maxHp: hp,
    speed: (archer ? 82 : 88) * mods.speed * game.rng.range(0.92, 1.1),
    sense: (238 + night * 40) * mods.sense,
    dmg: 9 + night * 4 + Math.min(6, game.time.day * 0.8),
    type: archer ? 'archer' : 'hollow',
    shield: !archer && game.chronicle.has('shielded') && game.rng.chance(0.78),
    archer,
    aggro: !!opts.aggro,
    windup: 0,
    cd: game.rng.range(0.6, 2.2),
    root: 0,
    fear: 0,
    hurt: 0,
    dead: false,
    deathT: 0,
    fade: false,
    fadeT: 0,
    aiT: 0,
    walk: game.rng.range(0, TAU),
    spawnT: 0,
    seenTraps: new Set(),
    seed: game.rng.range(0, 1000)
  };
  game.enemies.push(e);
  game.addParticles('smoke', x, y, 8, {});
  game.addParticles('soul', x, y - 8, 4, {});
  return e;
}

export function spawnWave(game, cairn, count) {
  for (let i = 0; i < count; i++) {
    const a = (i / count) * TAU + game.rng.range(-0.3, 0.3);
    const r = 235 + game.rng.range(0, 60);
    const x = clamp(cairn.x + Math.cos(a) * r, 80, game.world.w - 80);
    const y = clamp(cairn.y + Math.sin(a) * r, 80, game.world.h - 80);
    if (game.world.waterAt(x, y)) continue;
    const e = spawnEnemy(game, { x, y, aggro: true });
    e.aggro = true;
  }
  game.ui.toast('The cairn’s light wakes something.', 'danger', 3200);
}

export function updateEnemies(game, dt) {
  const p = game.player;
  const mods = game.chronicle.mods();

  for (let i = game.enemies.length - 1; i >= 0; i--) {
    const e = game.enemies[i];
    if (e.dead) {
      e.deathT += dt;
      if (e.deathT > 1.4) game.enemies.splice(i, 1);
      continue;
    }
    if (e.fade) {
      e.fadeT += dt;
      if (e.fadeT > 1.2) game.enemies.splice(i, 1);
      continue;
    }
    e.spawnT = Math.min(1, e.spawnT + dt * 2.2);
    e.walk += dt * (2.5 + e.speed / 90);
    e.hurt = Math.max(0, e.hurt - dt);
    e.root = Math.max(0, e.root - dt);
    e.fear = Math.max(0, e.fear - dt);
    e.cd = Math.max(0, e.cd - dt);
    if (p.dead) continue;

    const d = dist(e.x, e.y, p.x, p.y);
    const detection = e.sense * (p.sneak ? 0.54 : 1);

    if (!e.aggro && d < detection) {
      e.aiT -= dt;
      if (e.aiT <= 0) {
        e.aiT = 0.35;
        if (hasLineOfSight(game.world, e.x, e.y, p.x, p.y)) {
          e.aggro = true;
          game.addFloat('!', e.x, e.y - 34, '#c94f43', 17);
          game.audio.sfx('trap');
        }
      }
    }
    if (e.aggro && d > 1350) e.aggro = false;

    let dx = 0, dy = 0, speed = e.speed;

    if (e.fear > 0) {
      const a = Math.atan2(e.y - p.y, e.x - p.x);
      dx = Math.cos(a);
      dy = Math.sin(a);
      speed *= 1.18;
    } else if (e.root > 0) {
      dx = 0; dy = 0;
      if (game.rng.chance(dt * 3)) game.addParticles('dust', e.x, e.y + 6, 1, {});
    } else if (e.aggro) {
      if (e.archer) {
        if (d < 180) {
          const a = Math.atan2(e.y - p.y, e.x - p.x);
          dx = Math.cos(a); dy = Math.sin(a);
        } else if (d > 330) {
          const a = Math.atan2(p.y - e.y, p.x - e.x);
          dx = Math.cos(a); dy = Math.sin(a);
        } else {
          const a = Math.atan2(p.y - e.y, p.x - e.x) + Math.PI / 2 * (e.seed % 2 ? 1 : -1);
          dx = Math.cos(a) * 0.55; dy = Math.sin(a) * 0.55;
        }
        if (e.cd <= 0 && d < 460 && hasLineOfSight(game.world, e.x, e.y, p.x, p.y)) {
          e.cd = 2.2 + game.rng.next() * 1.2;
          const a = Math.atan2(p.y - e.y, p.x - e.x) + game.rng.range(-0.06, 0.06);
          game.projectiles.push({
            x: e.x + Math.cos(a) * 16, y: e.y + Math.sin(a) * 16 - 8,
            vx: Math.cos(a) * 390, vy: Math.sin(a) * 390,
            life: 2, angle: a, from: 'enemy', dmg: e.dmg * 0.7
          });
          game.audio.sfx('bow');
        }
        if (d < 50 && e.windup <= 0 && e.cd <= 0.1) {
          e.windup = 0.4;
        }
      } else {
        if (e.windup > 0) {
          e.windup -= dt;
          if (e.windup <= 0) {
            if (dist(e.x, e.y, p.x, p.y) < 56) game.hurtPlayer(e.dmg, e.x, e.y);
            e.cd = 1.05;
          }
        } else if (d < 56 && e.cd <= 0) {
          e.windup = 0.44;
          e.cd = 1.25;
          e.angle = Math.atan2(p.y - e.y, p.x - e.x);
        } else if (d > 34) {
          const a = Math.atan2(p.y - e.y, p.x - e.x) + Math.sin(e.walk * 0.7) * 0.16;
          dx = Math.cos(a); dy = Math.sin(a);
        }
      }
    } else {
      e.aiT -= dt;
      if (e.aiT <= 0) {
        e.aiT = 3 + game.rng.range(0, 3);
        const a = game.rng.range(0, TAU);
        const r = game.rng.range(20, 100);
        e.wanderX = e.spawnX + Math.cos(a) * r;
        e.wanderY = e.spawnY + Math.sin(a) * r;
      }
      const a = Math.atan2(e.wanderY - e.y, e.wanderX - e.x);
      if (dist(e.x, e.y, e.wanderX, e.wanderY) > 8) {
        dx = Math.cos(a); dy = Math.sin(a);
        speed *= 0.35;
      }
    }

    if (e.hurt > 0) speed *= 0.65;
    if (e.spawnT < 1) speed *= e.spawnT;

    // separation
    for (const o of game.enemies) {
      if (o === e || o.dead || o.fade) continue;
      const ox = e.x - o.x, oy = e.y - o.y;
      const od = Math.hypot(ox, oy);
      if (od > 0 && od < 30) {
        dx += (ox / od) * 0.6;
        dy += (oy / od) * 0.6;
      }
    }

    const len = Math.hypot(dx, dy);
    if (len > 0.01) {
      const nx = e.x + (dx / len) * speed * dt;
      const ny = e.y + (dy / len) * speed * dt;
      const res = resolveCollisions(game.world, nx, ny, e.r * 0.72);
      e.x = res.x;
      e.y = res.y;
      if (e.windup <= 0) e.angle = angleLerp(e.angle, Math.atan2(dy, dx), Math.min(1, dt * 6));
    }
    if (e.aggro && e.windup > 0) {
      e.angle = angleLerp(e.angle, Math.atan2(p.y - e.y, p.x - e.x), Math.min(1, dt * 8));
    }

    // hit player on contact if lunging
    if (e.windup > 0 && e.windup < 0.2 && dist(e.x, e.y, p.x, p.y) < 60) {
      // handled at windup completion
    }
  }
}

export function damageEnemy(game, e, amount, source = 'melee', crit = false) {
  if (e.dead) return;
  const mods = game.chronicle.mods();
  let dmg = amount;
  if (source === 'arrow') dmg *= 1 - mods.rangedResist;
  if (source === 'ember' && mods.fireResist) dmg *= 0.5;
  if (e.shield && source === 'melee') dmg *= 0.92;
  dmg = Math.max(1, Math.round(dmg));
  e.hp -= dmg;
  e.hurt = 0.22;
  e.aggro = true;
  game.addFloat(`${crit ? 'SILENT ' : ''}${dmg}`, e.x, e.y - 32, crit ? '#f0c07a' : '#e9e1cf', crit ? 13 : 11);
  game.addParticles('blood', e.x, e.y - 6, crit ? 12 : 4, {});
  game.audio.sfx('hit');

  if (source === 'arrow') {
    game.record({
      kind: 'bow',
      text: `Your arrow found a Hollowed in ${game.locationName()}.`,
      traits: { bow: 1 },
      x: e.x, y: e.y
    });
  }

  if (e.hp <= 0) {
    e.dead = true;
    e.deathT = 0;
    game.addParticles('soul', e.x, e.y - 10, 14, {});
    game.addParticles('blood', e.x, e.y, 10, {});
    game.audio.sfx('hit');
    const loc = game.locationName();
    let text = `You put a Hollowed down in ${loc}.`;
    if (source === 'arrow') text = `An arrow put a Hollowed down in ${loc}.`;
    if (source === 'trap') text = `Your snare took a Hollowed in ${loc}.`;
    if (crit) text = `You killed a Hollowed silently in ${loc}.`;
    const traits = { kills: 1 };
    if (crit) traits.shadow = 1;
    game.record({ kind: 'kill', text, traits, x: e.x, y: e.y });
    if (crit && game.ui) game.ui.toast('A silent kill. The dark did not hear you coming.', 'good', 2400);
    if (e.archer) {
      game.player.arrows += 2;
      game.addFloat('+2 arrows', e.x, e.y - 18, '#d8c9a2', 10);
    }
  }
}

/* ============================================================
   PROJECTILES & TRAPS
   ============================================================ */
function solidAt(world, x, y) {
  const cell = world.colCell;
  const cx = Math.floor(x / cell), cy = Math.floor(y / cell);
  for (let gx = cx - 1; gx <= cx + 1; gx++) {
    for (let gy = cy - 1; gy <= cy + 1; gy++) {
      const list = world.colGrid.get(`${gx},${gy}`);
      if (!list) continue;
      for (const c of list) {
        if (c.prop && (c.prop.done || c.prop.kind === 'garden' || c.prop.kind === 'lantern')) continue;
        if ((x - c.x) ** 2 + (y - c.y) ** 2 < (c.r + 2) ** 2) return true;
      }
    }
  }
  return false;
}

export function updateProjectiles(game, dt) {
  for (let i = game.projectiles.length - 1; i >= 0; i--) {
    const pr = game.projectiles[i];
    pr.life -= dt;
    pr.x += pr.vx * dt;
    pr.y += pr.vy * dt;
    let remove = pr.life <= 0;
    if (pr.x < 0 || pr.y < 0 || pr.x > game.world.w || pr.y > game.world.h) remove = true;

    if (!remove && solidAt(game.world, pr.x, pr.y)) {
      remove = true;
      game.addParticles('dust', pr.x, pr.y, 3, { color: '#8d886c' });
    }

    if (!remove && pr.from === 'player') {
      for (const e of game.enemies) {
        if (e.dead || e.fade) continue;
        if (dist(pr.x, pr.y, e.x, e.y) < e.r + 7) {
          damageEnemy(game, e, pr.dmg, 'arrow');
          remove = true;
          break;
        }
      }
      if (!remove) {
        for (const a of [...game.animals]) {
          if (dist(pr.x, pr.y, a.x, a.y) < 16) {
            a.hp -= pr.dmg;
            a.hit = 0.2;
            game.addParticles('blood', a.x, a.y, 6, {});
            game.addFloat(`-${Math.round(pr.dmg)}`, a.x, a.y - 18, '#d8c9a2', 11);
            if (a.hp <= 0) game.killAnimal(a, true);
            remove = true;
            break;
          }
        }
      }
    } else if (!remove && pr.from === 'enemy') {
      const p = game.player;
      if (dist(pr.x, pr.y, p.x, p.y) < p.r + 5) {
        game.hurtPlayer(pr.dmg, pr.x, pr.y);
        remove = true;
      }
    }

    if (remove) game.projectiles.splice(i, 1);
  }
}

export function updateTraps(game, dt) {
  const mods = game.chronicle.mods();
  for (const t of game.traps) {
    if (!t.armed) continue;
    for (const e of game.enemies) {
      if (e.dead || e.fade || e.root > 0) continue;
      if (dist(e.x, e.y, t.x, t.y) > 38) continue;
      if (mods.trapSense > 0 && !e.seenTraps.has(t.uid) && game.rng.chance(0.72)) {
        e.seenTraps.add(t.uid);
        game.addFloat('AVOIDED', t.x, t.y - 16, '#8f9bc4', 9);
        continue;
      }
      t.armed = false;
      e.root = 3.4;
      e.windup = 0;
      e.aggro = true;
      game.audio.sfx('trap');
      game.addParticles('dust', t.x, t.y, 10, {});
      game.addParticles('blood', t.x, t.y, 5, {});
      damageEnemy(game, e, 20, 'trap');
      game.record({
        kind: 'snare', text: `A snare caught a Hollowed in ${game.locationName()}.`,
        traits: { snare: 1 }, x: t.x, y: t.y
      });
      break;
    }
  }
}

import { TAU, clamp, rgba, shadeHex } from './util.js';
import { glyphForKind } from './memory.js';
import { TOOLS } from './config.js';

const rid = (seed, i = 0) => {
  const x = Math.sin(seed * 12.9898 + i * 78.233) * 43758.5453;
  return x - Math.floor(x);
};

export function shadow(ctx, x, y, rx, ry, a = 0.26) {
  ctx.fillStyle = `rgba(4, 8, 6, ${a})`;
  ctx.beginPath();
  ctx.ellipse(x + rx * 0.22, y + ry * 0.36, rx, ry, 0, 0, TAU);
  ctx.fill();
}

/* ============================================================
   PROPS
   ============================================================ */
export function drawProp(ctx, p, t) {
  if (p.done) {
    if (p.kind === 'pine' || p.kind === 'oak' || p.kind === 'dead') return drawStump(ctx, p);
    if (p.kind === 'rock') return drawRubble(ctx, p);
    return;
  }
  switch (p.kind) {
    case 'pine': return drawPine(ctx, p, t);
    case 'oak': return drawOak(ctx, p, t);
    case 'dead': return drawDeadTree(ctx, p, t);
    case 'rock': return drawRock(ctx, p);
    case 'bush': return drawBush(ctx, p, t);
    case 'reed': return drawReed(ctx, p, t);
    case 'flower': return drawFlower(ctx, p);
    case 'mushroom': return drawMushroom(ctx, p);
    case 'stump': return drawStump(ctx, p);
    case 'bone': return drawBone(ctx, p);
    case 'log': return drawLog(ctx, p);
    case 'crate': return drawCrate(ctx, p);
    case 'barrel': return drawBarrel(ctx, p);
    case 'garden': return drawGarden(ctx, p);
    case 'banner': return drawBanner(ctx, p, t);
    case 'lantern': return drawLantern(ctx, p, t);
    case 'sign': return drawSign(ctx, p);
    case 'ruinPillar': return drawPillar(ctx, p);
    case 'ruinWall': return drawRuinWall(ctx, p);
    case 'standingStone': return drawStandingStone(ctx, p, t);
    case 'cache': return drawCache(ctx, p);
    default: return null;
  }
}

function drawPine(ctx, p, t) {
  const s = p.s;
  const sway = Math.sin(t * 0.9 + p.seed) * 1.6;
  shadow(ctx, p.x, p.y, 17 * s, 6.5 * s);
  ctx.fillStyle = '#3c3327';
  ctx.fillRect(p.x - 2.2 * s, p.y - 20 * s, 4.4 * s, 20 * s);
  const layers = [
    { y: -12, w: 24, h: 30, c: '#2c3c2a' },
    { y: -30, w: 19, h: 28, c: '#33452f' },
    { y: -48, w: 13, h: 24, c: '#3b4e34' }
  ];
  for (let i = 0; i < layers.length; i++) {
    const L = layers[i];
    const x = p.x + sway * (0.4 + i * 0.4);
    const baseY = p.y + L.y * s;
    ctx.fillStyle = L.c;
    ctx.beginPath();
    ctx.moveTo(x, baseY - L.h * s);
    ctx.lineTo(x - L.w * s, baseY);
    ctx.quadraticCurveTo(x, baseY + 4 * s, x + L.w * s, baseY);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(190, 208, 150, 0.07)';
    ctx.beginPath();
    ctx.moveTo(x, baseY - L.h * s);
    ctx.lineTo(x - L.w * 0.55 * s, baseY - 2 * s);
    ctx.lineTo(x - L.w * 0.1 * s, baseY - 2 * s);
    ctx.closePath();
    ctx.fill();
  }
}

function drawOak(ctx, p, t) {
  const s = p.s;
  const sway = Math.sin(t * 0.7 + p.seed) * 1.2;
  shadow(ctx, p.x, p.y, 23 * s, 8 * s);
  ctx.fillStyle = '#4a3a28';
  ctx.fillRect(p.x - 2.8 * s, p.y - 26 * s, 5.6 * s, 26 * s);
  ctx.strokeStyle = '#4a3a28';
  ctx.lineWidth = 3 * s;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y - 20 * s);
  ctx.lineTo(p.x - 8 * s + sway * 0.3, p.y - 34 * s);
  ctx.moveTo(p.x, p.y - 22 * s);
  ctx.lineTo(p.x + 9 * s + sway * 0.3, p.y - 36 * s);
  ctx.stroke();

  const blobs = [
    [-13, -44, 15, '#44532f'],
    [12, -46, 16, '#4a5a34'],
    [0, -55, 18, '#526238'],
    [-4, -36, 16, '#4d5c33'],
    [6, -34, 14, '#42512e']
  ];
  for (const [bx, by, br, col] of blobs) {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.arc(p.x + bx * s + sway, p.y + by * s, br * s, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(200, 215, 150, 0.1)';
  ctx.beginPath();
  ctx.arc(p.x - 7 * s + sway, p.y - 50 * s, 9 * s, 0, TAU);
  ctx.fill();
}

function drawDeadTree(ctx, p, t) {
  const s = p.s;
  const sway = Math.sin(t * 0.6 + p.seed) * 1.2;
  shadow(ctx, p.x, p.y, 11 * s, 4 * s, 0.22);
  ctx.strokeStyle = '#6a5f50';
  ctx.lineWidth = 3.2 * s;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x + sway * 0.4, p.y - 40 * s);
  ctx.moveTo(p.x + sway * 0.2, p.y - 24 * s);
  ctx.lineTo(p.x - 14 * s, p.y - 38 * s);
  ctx.moveTo(p.x + sway * 0.3, p.y - 30 * s);
  ctx.lineTo(p.x + 13 * s, p.y - 48 * s);
  ctx.moveTo(p.x - 6 * s, p.y - 32 * s);
  ctx.lineTo(p.x - 17 * s, p.y - 52 * s);
  ctx.stroke();
  ctx.lineWidth = 1.4 * s;
  ctx.beginPath();
  ctx.moveTo(p.x - 14 * s, p.y - 38 * s);
  ctx.lineTo(p.x - 20 * s, p.y - 45 * s);
  ctx.moveTo(p.x + 13 * s, p.y - 48 * s);
  ctx.lineTo(p.x + 19 * s, p.y - 55 * s);
  ctx.stroke();
  ctx.lineCap = 'butt';
}

function drawRock(ctx, p) {
  const s = p.s;
  const n = 7;
  shadow(ctx, p.x, p.y, 17 * s, 6 * s, 0.24);
  ctx.beginPath();
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU;
    const rr = (12 + rid(p.seed, i) * 8) * s;
    const x = p.x + Math.cos(a) * rr;
    const y = p.y - 4 * s + Math.sin(a) * rr * 0.72;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = '#666860';
  ctx.fill();
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const a = -Math.PI * 0.85 + i * 0.38;
    const x = p.x + Math.cos(a) * 12 * s;
    const y = p.y - 8 * s + Math.sin(a) * 11 * s;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.strokeStyle = 'rgba(210, 212, 196, 0.18)';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = 'rgba(80, 88, 62, 0.35)';
  ctx.beginPath();
  ctx.arc(p.x - 6 * s, p.y + 2 * s, 4 * s, 0, TAU);
  ctx.fill();
}

function drawBush(ctx, p) {
  const s = p.s;
  shadow(ctx, p.x, p.y, 13 * s, 5 * s, 0.2);
  ctx.fillStyle = '#42512f';
  ctx.beginPath();
  ctx.arc(p.x - 6 * s, p.y - 8 * s, 9 * s, 0, TAU);
  ctx.arc(p.x + 5 * s, p.y - 9 * s, 10 * s, 0, TAU);
  ctx.arc(p.x, p.y - 15 * s, 8 * s, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(170, 196, 120, 0.14)';
  ctx.beginPath();
  ctx.arc(p.x - 4 * s, p.y - 17 * s, 5 * s, 0, TAU);
  ctx.fill();
  if (!p.harvested) {
    for (let i = 0; i < (p.berries || 2); i++) {
      const a = rid(p.seed, i) * TAU;
      const r = 4 + rid(p.seed, i + 4) * 8;
      ctx.fillStyle = '#a45b3f';
      ctx.beginPath();
      ctx.arc(p.x + Math.cos(a) * r * s, p.y - 11 * s + Math.sin(a) * r * 0.6 * s, 1.8 * s, 0, TAU);
      ctx.fill();
    }
  }
}

function drawReed(ctx, p, t) {
  const s = p.s;
  const sway = Math.sin(t * 1.3 + p.seed) * 4;
  ctx.strokeStyle = '#6f7c4b';
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 5; i++) {
    const off = (i - 2) * 3.2 * s;
    ctx.beginPath();
    ctx.moveTo(p.x + off, p.y);
    ctx.quadraticCurveTo(p.x + off + sway * 0.3, p.y - 18 * s, p.x + off + sway, p.y - 28 * s - i * 2);
    ctx.stroke();
  }
  ctx.fillStyle = '#8a7c4e';
  ctx.beginPath();
  ctx.ellipse(p.x + sway, p.y - 29 * s, 1.6, 4, 0.3, 0, TAU);
  ctx.fill();
}

function drawFlower(ctx, p) {
  const s = p.s;
  ctx.strokeStyle = '#5f6c41';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x + 1 * s, p.y - 8 * s);
  ctx.stroke();
  ctx.fillStyle = p.hue || '#d8b46a';
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU;
    ctx.beginPath();
    ctx.arc(p.x + Math.cos(a) * 2.2 * s, p.y - 9 * s + Math.sin(a) * 2.2 * s, 1.6 * s, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = '#efe6c8';
  ctx.beginPath();
  ctx.arc(p.x, p.y - 9 * s, 1.2 * s, 0, TAU);
  ctx.fill();
}

function drawMushroom(ctx, p) {
  const s = p.s;
  ctx.fillStyle = '#d6cdb2';
  ctx.fillRect(p.x - 1, p.y - 6 * s, 2, 6 * s);
  ctx.fillStyle = '#9c5f44';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 7 * s, 4.5 * s, 3 * s, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(233, 225, 207, 0.5)';
  ctx.beginPath();
  ctx.arc(p.x - 1.5 * s, p.y - 8 * s, 0.8 * s, 0, TAU);
  ctx.fill();
}

function drawStump(ctx, p) {
  const s = p.s;
  shadow(ctx, p.x, p.y, 9 * s, 4 * s, 0.2);
  ctx.fillStyle = '#51402c';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 3 * s, 9 * s, 6 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(200, 180, 140, 0.25)';
  ctx.lineWidth = 1;
  for (let i = 1; i <= 2; i++) {
    ctx.beginPath();
    ctx.ellipse(p.x, p.y - 3 * s, (9 - i * 2.5) * s, (6 - i * 1.6) * s, 0, 0, TAU);
    ctx.stroke();
  }
}

function drawBone(ctx, p) {
  const s = p.s;
  ctx.strokeStyle = '#c9c2aa';
  ctx.lineWidth = 1.8;
  ctx.lineCap = 'round';
  const a = rid(p.seed, 1) * TAU;
  ctx.beginPath();
  ctx.moveTo(p.x - Math.cos(a) * 7 * s, p.y - Math.sin(a) * 4 * s);
  ctx.lineTo(p.x + Math.cos(a) * 7 * s, p.y + Math.sin(a) * 4 * s);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(p.x - Math.cos(a) * 7 * s, p.y - Math.sin(a) * 4 * s, 1.8, 0, TAU);
  ctx.arc(p.x + Math.cos(a) * 7 * s, p.y + Math.sin(a) * 4 * s, 1.8, 0, TAU);
  ctx.fillStyle = '#c9c2aa';
  ctx.fill();
  ctx.lineCap = 'butt';
}

function drawLog(ctx, p) {
  const s = p.s;
  const a = rid(p.seed, 2) * TAU;
  shadow(ctx, p.x, p.y, 13 * s, 5 * s, 0.18);
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(a);
  ctx.fillStyle = '#4f3f2b';
  ctx.beginPath();
  ctx.roundRect(-12 * s, -4.5 * s, 24 * s, 9 * s, 4 * s);
  ctx.fill();
  ctx.fillStyle = '#6d5638';
  ctx.beginPath();
  ctx.ellipse(12 * s, 0, 3.6 * s, 4.5 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(40, 30, 20, 0.5)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(12 * s, 0, 2 * s, 2.6 * s, 0, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

function drawCrate(ctx, p) {
  shadow(ctx, p.x, p.y, 11, 4, 0.22);
  ctx.fillStyle = '#6a5233';
  ctx.fillRect(p.x - 9, p.y - 20, 18, 20);
  ctx.strokeStyle = '#3c2c1a';
  ctx.lineWidth = 1.4;
  ctx.strokeRect(p.x - 9, p.y - 20, 18, 20);
  ctx.beginPath();
  ctx.moveTo(p.x - 9, p.y - 20);
  ctx.lineTo(p.x + 9, p.y);
  ctx.moveTo(p.x + 9, p.y - 20);
  ctx.lineTo(p.x - 9, p.y);
  ctx.stroke();
  ctx.fillStyle = '#b9b09a';
  ctx.fillRect(p.x - 3, p.y - 12, 6, 2);
}

function drawBarrel(ctx, p) {
  shadow(ctx, p.x, p.y, 9, 3, 0.2);
  ctx.fillStyle = '#5e472c';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 10, 8, 10, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#2f2519';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 15, 8, 2.6, 0, 0, TAU);
  ctx.moveTo(p.x - 8, p.y - 7);
  ctx.lineTo(p.x + 8, p.y - 7);
  ctx.stroke();
}

function drawGarden(ctx, p) {
  const a = p.angle || 0;
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(a);
  ctx.fillStyle = '#57462f';
  ctx.beginPath();
  ctx.roundRect(-30, -18, 60, 36, 5);
  ctx.fill();
  ctx.strokeStyle = 'rgba(40, 32, 20, 0.5)';
  ctx.lineWidth = 1;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(-26, i * 10);
    ctx.lineTo(26, i * 10);
    ctx.stroke();
  }
  if (!p.stolen) {
    for (let r = -1; r <= 1; r++) {
      for (let c = -2; c <= 2; c++) {
        ctx.fillStyle = (c + r) % 2 ? '#6f8047' : '#7d8d50';
        ctx.beginPath();
        ctx.arc(c * 10, r * 10 - 2, 3.2, 0, TAU);
        ctx.fill();
      }
    }
  }
  ctx.restore();
}

function drawBanner(ctx, p, t) {
  const s = p.s;
  const wave = Math.sin(t * 2 + p.seed) * 3;
  shadow(ctx, p.x, p.y, 5, 2, 0.18);
  ctx.strokeStyle = '#4c3a25';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x, p.y - 52 * s);
  ctx.stroke();
  ctx.fillStyle = p.hue || '#7c3f2e';
  ctx.beginPath();
  ctx.moveTo(p.x, p.y - 50 * s);
  ctx.quadraticCurveTo(p.x + 20 * s + wave, p.y - 44 * s, p.x + 24 * s + wave, p.y - 36 * s);
  ctx.lineTo(p.x + 12 * s, p.y - 32 * s);
  ctx.lineTo(p.x, p.y - 38 * s);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(233, 225, 207, 0.35)';
  ctx.beginPath();
  ctx.arc(p.x + 8 * s, p.y - 41 * s, 2.2, 0, TAU);
  ctx.fill();
}

function drawLantern(ctx, p, t) {
  ctx.strokeStyle = '#3d3223';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x, p.y - 30);
  ctx.lineTo(p.x + 7, p.y - 30);
  ctx.stroke();
  const flick = 0.75 + Math.sin(t * 4 + p.seed) * 0.15;
  ctx.fillStyle = 'rgba(240, 176, 100, 0.85)';
  ctx.beginPath();
  ctx.roundRect(p.x + 4, p.y - 29, 6, 8, 1.5);
  ctx.fill();
  ctx.fillStyle = `rgba(240, 176, 100, ${0.16 * flick})`;
  ctx.beginPath();
  ctx.arc(p.x + 7, p.y - 25, 12, 0, TAU);
  ctx.fill();
}

function drawSign(ctx, p) {
  shadow(ctx, p.x, p.y, 6, 2, 0.18);
  ctx.strokeStyle = '#4b3a25';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x, p.y - 30);
  ctx.stroke();
  ctx.save();
  ctx.translate(p.x, p.y - 26);
  ctx.rotate(p.angle || 0);
  ctx.fillStyle = '#685232';
  ctx.fillRect(-14, -6, 28, 11);
  ctx.fillStyle = 'rgba(233, 225, 207, 0.35)';
  ctx.fillRect(-10, -3, 12, 1.2);
  ctx.fillRect(-10, 0, 8, 1.2);
  ctx.restore();
}

function drawPillar(ctx, p) {
  const s = p.s;
  shadow(ctx, p.x, p.y, 15 * s, 5 * s, 0.24);
  ctx.fillStyle = '#767468';
  ctx.beginPath();
  ctx.roundRect(p.x - 9 * s, p.y - 12 * s, 18 * s, 12 * s, 2);
  ctx.fill();
  ctx.fillStyle = '#8a8778';
  ctx.beginPath();
  ctx.roundRect(p.x - 7 * s, p.y - 42 * s, 14 * s, 32 * s, 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(50, 54, 48, 0.35)';
  ctx.fillRect(p.x - 7 * s, p.y - 20 * s, 14 * s, 2);
  ctx.fillRect(p.x - 7 * s, p.y - 30 * s, 14 * s, 2);
  ctx.fillStyle = '#5f5d54';
  ctx.beginPath();
  ctx.moveTo(p.x - 7 * s, p.y - 42 * s);
  ctx.lineTo(p.x + 2 * s, p.y - 47 * s);
  ctx.lineTo(p.x + 7 * s, p.y - 40 * s);
  ctx.lineTo(p.x + 3 * s, p.y - 37 * s);
  ctx.closePath();
  ctx.fill();
}

function drawRuinWall(ctx, p) {
  const s = p.s;
  shadow(ctx, p.x, p.y, 30 * s, 6 * s, 0.22);
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot || 0);
  ctx.fillStyle = '#6f6d61';
  ctx.beginPath();
  ctx.roundRect(-p.len * s * 0.5, -14 * s, p.len * s, 16 * s, 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(40, 42, 38, 0.35)';
  ctx.lineWidth = 1;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 18 * s, -14 * s);
    ctx.lineTo(i * 18 * s, 2 * s);
    ctx.stroke();
  }
  ctx.fillStyle = 'rgba(200, 200, 180, 0.12)';
  ctx.fillRect(-p.len * s * 0.5, -14 * s, p.len * s, 2);
  ctx.restore();
}

function drawStandingStone(ctx, p, t) {
  const s = p.s;
  shadow(ctx, p.x, p.y, 13 * s, 6 * s, 0.26);
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate((p.rot || 0) * 0.06);
  ctx.fillStyle = '#6b6c62';
  ctx.beginPath();
  ctx.moveTo(-8 * s, 0);
  ctx.quadraticCurveTo(-10 * s, -34 * s, -3 * s, -48 * s);
  ctx.quadraticCurveTo(4 * s, -52 * s, 8 * s, -42 * s);
  ctx.quadraticCurveTo(9 * s, -18 * s, 8 * s, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(210, 212, 190, 0.18)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-4 * s, -40 * s);
  ctx.lineTo(1 * s, -33 * s);
  ctx.lineTo(-3 * s, -27 * s);
  ctx.lineTo(2 * s, -20 * s);
  ctx.stroke();
  ctx.restore();
}

function drawCache(ctx, p) {
  shadow(ctx, p.x, p.y, 14, 5, 0.24);
  ctx.fillStyle = '#4a3722';
  ctx.beginPath();
  ctx.roundRect(p.x - 12, p.y - 20, 24, 20, 2);
  ctx.fill();
  ctx.strokeStyle = '#c7a76a';
  ctx.lineWidth = 1.4;
  ctx.strokeRect(p.x - 10, p.y - 18, 20, 16);
  ctx.fillStyle = '#c7a76a';
  ctx.fillRect(p.x - 2, p.y - 12, 4, 5);
  const glow = 0.4 + Math.sin(p.seed) * 0.1;
  ctx.fillStyle = `rgba(216, 180, 106, ${glow * 0.18})`;
  ctx.beginPath();
  ctx.arc(p.x, p.y - 10, 20, 0, TAU);
  ctx.fill();
}

function drawRubble(ctx, p) {
  ctx.fillStyle = '#5c5e56';
  for (let i = 0; i < 4; i++) {
    const a = rid(p.seed, i) * TAU;
    ctx.beginPath();
    ctx.ellipse(p.x + Math.cos(a) * 8, p.y + Math.sin(a) * 4, 3 + rid(p.seed, i + 4) * 3, 2.4, 0, 0, TAU);
    ctx.fill();
  }
}

/* ============================================================
   VILLAGE
   ============================================================ */
export function drawHut(ctx, h, t, night) {
  shadow(ctx, h.x, h.y, h.r * 1.05, h.r * 0.42, 0.32);
  ctx.fillStyle = '#57452f';
  ctx.beginPath();
  ctx.ellipse(h.x, h.y, h.r * 0.88, h.r * 0.62, 0, 0, TAU);
  ctx.fill();

  ctx.fillStyle = h.color || '#6b5438';
  ctx.beginPath();
  ctx.arc(h.x, h.y - 6, h.r, 0, TAU);
  ctx.fill();

  const grad = ctx.createRadialGradient(h.x - h.r * 0.35, h.y - h.r * 0.45, h.r * 0.15, h.x, h.y, h.r);
  grad.addColorStop(0, '#8a6c44');
  grad.addColorStop(0.55, '#6a5133');
  grad.addColorStop(1, '#473522');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(h.x, h.y - 8, h.r, 0, TAU);
  ctx.fill();

  ctx.strokeStyle = 'rgba(42, 30, 18, 0.3)';
  ctx.lineWidth = 1.1;
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * TAU;
    ctx.beginPath();
    ctx.moveTo(h.x, h.y - 8);
    ctx.lineTo(h.x + Math.cos(a) * h.r, h.y - 8 + Math.sin(a) * h.r);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(233, 210, 160, 0.22)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(h.x, h.y - 8, h.r * 0.92, Math.PI * 1.05, Math.PI * 1.75);
  ctx.stroke();

  // door faces the hearth
  ctx.save();
  ctx.translate(h.x, h.y - 6);
  ctx.rotate(h.doorAngle);
  ctx.fillStyle = '#221a12';
  ctx.beginPath();
  ctx.ellipse(h.r * 0.72, 0, 10, 14, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(224, 138, 68, 0.55)';
  if (night > 0.25) {
    ctx.beginPath();
    ctx.ellipse(h.r * 0.72, 0, 3.2, 5, 0, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // hanging charm
  ctx.fillStyle = 'rgba(216, 180, 106, 0.6)';
  ctx.beginPath();
  ctx.arc(h.x - h.r * 0.55, h.y - h.r * 0.25, 2.2, 0, TAU);
  ctx.fill();
}

export function drawHearthBase(ctx, x, y) {
  ctx.fillStyle = '#4a4438';
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * TAU;
    ctx.beginPath();
    ctx.ellipse(x + Math.cos(a) * 24, y + Math.sin(a) * 15, 5, 3.4, a, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(30, 26, 20, 0.5)';
  ctx.beginPath();
  ctx.ellipse(x, y, 20, 12, 0, 0, TAU);
  ctx.fill();
}

/* ============================================================
   CAIRN
   ============================================================ */
export function drawCairn(ctx, c, t) {
  const lit = c.lit;
  ctx.save();
  if (lit) {
    const g = ctx.createRadialGradient(c.x, c.y, 10, c.x, c.y, 150);
    g.addColorStop(0, 'rgba(224, 138, 68, 0.15)');
    g.addColorStop(1, 'rgba(224, 138, 68, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(c.x, c.y, 150, 0, TAU);
    ctx.fill();
  }

  ctx.strokeStyle = lit ? 'rgba(224, 138, 68, 0.4)' : 'rgba(200, 200, 180, 0.12)';
  ctx.lineWidth = 1.2;
  ctx.setLineDash([6, 8]);
  ctx.beginPath();
  ctx.arc(c.x, c.y, 104, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);

  shadow(ctx, c.x, c.y, 30, 11, 0.3);
  const stones = [
    [0, 0, 26, 13],
    [-3, -8, 22, 11],
    [1, -15, 17, 9],
    [-1, -21, 12, 7],
    [2, -26, 8, 5]
  ];
  for (let i = 0; i < stones.length; i++) {
    const [ox, oy, rx, ry] = stones[i];
    ctx.fillStyle = i % 2 ? '#6a6b61' : '#77786c';
    ctx.beginPath();
    ctx.ellipse(c.x + ox, c.y + oy, rx, ry, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(220, 222, 200, 0.1)';
    ctx.beginPath();
    ctx.ellipse(c.x + ox - rx * 0.2, c.y + oy - ry * 0.3, rx * 0.5, ry * 0.4, 0, 0, TAU);
    ctx.fill();
  }
  if (lit) {
    ctx.fillStyle = 'rgba(240, 176, 100, 0.9)';
    ctx.beginPath();
    ctx.arc(c.x + 2, c.y - 30, 3.4, 0, TAU);
    ctx.fill();
    const glow = ctx.createRadialGradient(c.x + 2, c.y - 30, 1, c.x + 2, c.y - 30, 26);
    glow.addColorStop(0, 'rgba(240, 190, 120, 0.55)');
    glow.addColorStop(1, 'rgba(240, 190, 120, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(c.x + 2, c.y - 30, 26, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ============================================================
   FIRES
   ============================================================ */
export function drawFire(ctx, f, t) {
  const big = f.eternal ? 1.25 : 1;
  if (!f.eternal) {
    ctx.fillStyle = '#4a4438';
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * TAU;
      ctx.beginPath();
      ctx.ellipse(f.x + Math.cos(a) * 19, f.y + Math.sin(a) * 10, 4.4, 3, a, 0, TAU);
      ctx.fill();
    }
  }
  ctx.save();
  ctx.translate(f.x, f.y);
  ctx.rotate(-0.25);
  ctx.fillStyle = '#4a3521';
  ctx.beginPath();
  ctx.roundRect(-11 * big, -3 * big, 22 * big, 5 * big, 2);
  ctx.fill();
  ctx.rotate(0.55);
  ctx.beginPath();
  ctx.roundRect(-10 * big, -3 * big, 20 * big, 5 * big, 2);
  ctx.fill();
  ctx.restore();

  const flick = Math.sin(t * 8.5 + f.seed) * 0.16 + Math.sin(t * 13 + f.seed * 2) * 0.08;
  const h = (34 + flick * 30) * big;
  const layers = [
    { w: 15, h: 1, c: 'rgba(224, 90, 40, 0.85)' },
    { w: 10, h: 0.76, c: 'rgba(240, 150, 70, 0.95)' },
    { w: 5.5, h: 0.52, c: 'rgba(255, 220, 160, 0.95)' }
  ];
  for (const L of layers) {
    const w = L.w * big;
    const hh = h * L.h;
    ctx.fillStyle = L.c;
    ctx.beginPath();
    ctx.moveTo(f.x - w, f.y - 2);
    ctx.quadraticCurveTo(f.x - w * 0.8, f.y - hh * 0.5, f.x + flick * 12, f.y - hh);
    ctx.quadraticCurveTo(f.x + w * 0.9, f.y - hh * 0.5, f.x + w, f.y - 2);
    ctx.closePath();
    ctx.fill();
  }
}

/* ============================================================
   PEOPLE
   ============================================================ */
export function drawPlayer(ctx, p, game) {
  const t = game.t;
  const bob = p.bob;
  shadow(ctx, p.x, p.y + 4, p.sneak ? 11 : 13, 5, 0.3);
  if (p.inWater) {
    ctx.strokeStyle = 'rgba(170, 205, 205, 0.35)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.ellipse(p.x, p.y + 5, 16 + Math.sin(t * 4) * 2, 6, 0, 0, TAU);
    ctx.stroke();
  }
  ctx.save();
  ctx.translate(p.x, p.y + bob * 0.35);
  ctx.rotate(p.angle);
  const sc = p.sneak ? 0.9 : 1;
  ctx.scale(sc, sc);
  if (p.invuln > 0 && Math.floor(t * 14) % 2 === 0) ctx.globalAlpha = 0.7;

  // cloak tail
  ctx.fillStyle = '#3c4636';
  ctx.beginPath();
  ctx.moveTo(-10, -8);
  ctx.quadraticCurveTo(-26 - Math.sin(t * 3) * 2, -2, -20, 10);
  ctx.quadraticCurveTo(-10, 10, -6, 5);
  ctx.closePath();
  ctx.fill();

  // body
  ctx.fillStyle = '#4b5540';
  ctx.beginPath();
  ctx.ellipse(0, 0, 10.5, 9, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#5a674a';
  ctx.beginPath();
  ctx.ellipse(-2, -2, 7, 6, 0, 0, TAU);
  ctx.fill();

  // scarf
  ctx.fillStyle = '#b56b47';
  ctx.beginPath();
  ctx.moveTo(1, -7);
  ctx.quadraticCurveTo(-6, -10 - Math.sin(t * 5) * 2, -14, -5);
  ctx.lineTo(-5, 0);
  ctx.closePath();
  ctx.fill();

  // head + hood
  ctx.fillStyle = '#c9b08a';
  ctx.beginPath();
  ctx.arc(6.5, 0, 5.4, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#3f4938';
  ctx.beginPath();
  ctx.arc(5, 0, 6.2, Math.PI * 0.6, Math.PI * 1.7);
  ctx.fill();
  ctx.fillStyle = 'rgba(30, 24, 16, 0.65)';
  ctx.beginPath();
  ctx.arc(9.5, 0, 3, -1.2, 1.2);
  ctx.fill();

  // tool
  const tool = TOOLS[p.tool];
  const swing = p.atkAnim > 0 ? Math.sin((1 - p.atkAnim / 0.24) * Math.PI) : 0;
  const handX = 7;
  const handY = 8;
  ctx.save();
  ctx.translate(handX, handY);
  ctx.rotate(-0.45 + swing * 1.5);
  if (tool.id === 'axe') {
    ctx.strokeStyle = '#5a4329';
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(0, 6);
    ctx.lineTo(0, -18);
    ctx.stroke();
    ctx.fillStyle = '#9aa0a0';
    ctx.beginPath();
    ctx.moveTo(0, -18);
    ctx.quadraticCurveTo(10, -20, 9, -10);
    ctx.lineTo(0, -9);
    ctx.closePath();
    ctx.fill();
  } else if (tool.id === 'spear') {
    ctx.strokeStyle = '#5a4329';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 8);
    ctx.lineTo(0, -34);
    ctx.stroke();
    ctx.fillStyle = '#a7aca6';
    ctx.beginPath();
    ctx.moveTo(0, -44);
    ctx.lineTo(3.5, -32);
    ctx.lineTo(-3.5, -32);
    ctx.closePath();
    ctx.fill();
  } else {
    ctx.strokeStyle = '#5a4329';
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.arc(0, -5, 13, -1.15, 1.15);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(220, 210, 180, 0.55)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(4.4, -17);
    ctx.lineTo(4.4, 5);
    ctx.stroke();
  }
  ctx.restore();

  // held light at night
  if (game.nightLevel() > 0.25) {
    const glow = ctx.createRadialGradient(2, 2, 2, 2, 2, 46);
    glow.addColorStop(0, 'rgba(240, 180, 110, 0.16)');
    glow.addColorStop(1, 'rgba(240, 180, 110, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(2, 2, 46, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
  ctx.globalAlpha = 1;

  // swing arc
  if (p.atkAnim > 0 && tool.melee) {
    const prog = 1 - p.atkAnim / 0.24;
    const a0 = p.swingAngle - tool.arc / 2 + prog * tool.arc * 0.8;
    const alpha = Math.sin(prog * Math.PI) * 0.45;
    ctx.strokeStyle = `rgba(233, 225, 207, ${alpha})`;
    ctx.lineWidth = 3.4;
    ctx.beginPath();
    ctx.arc(p.x, p.y - 2, tool.range * 0.85, a0 - 0.3, a0 + 0.3);
    ctx.stroke();
  }
}

export function drawNpc(ctx, n, game) {
  if (n.inside) return;
  const t = game.t;
  const bob = n.walking ? Math.sin(t * 8 + n.bob) * 1.8 : Math.sin(t * 1.4 + n.bob) * 0.5;
  shadow(ctx, n.x, n.y + 3, 11, 4.5, 0.26);
  ctx.save();
  ctx.translate(n.x, n.y + bob * 0.4);
  ctx.rotate(n.angle);
  const sc = n.id === 'orin' ? 0.78 : 1;
  ctx.scale(sc, sc);

  ctx.fillStyle = shadeHex(n.color || '#8a6a54', -0.35);
  ctx.beginPath();
  ctx.moveTo(-9, -7);
  ctx.quadraticCurveTo(-18, 0, -14, 8);
  ctx.lineTo(-2, 6);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = n.color || '#8a6a54';
  ctx.beginPath();
  ctx.ellipse(0, 0, 9.5, 8.4, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath();
  ctx.ellipse(-2, -3, 5.5, 4.4, 0, 0, TAU);
  ctx.fill();

  ctx.fillStyle = '#c9b08a';
  ctx.beginPath();
  ctx.arc(5.8, 0, 4.9, 0, TAU);
  ctx.fill();
  ctx.fillStyle = shadeHex(n.color || '#8a6a54', -0.2);
  ctx.beginPath();
  ctx.arc(4.6, 0, 5.6, Math.PI * 0.62, Math.PI * 1.66);
  ctx.fill();

  if (n.id === 'ivo') {
    // hunter's hood
    ctx.fillStyle = '#4f5a36';
    ctx.beginPath();
    ctx.ellipse(3, 0, 7.2, 6.2, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#c9b08a';
    ctx.beginPath();
    ctx.arc(8.4, 0, 3.4, 0, TAU);
    ctx.fill();
  }
  if (n.id === 'sable') {
    ctx.strokeStyle = '#5d4a32';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(6, 6);
    ctx.lineTo(14, 12);
    ctx.stroke();
    ctx.fillStyle = 'rgba(190, 200, 220, 0.7)';
    ctx.beginPath();
    ctx.arc(14.5, 12.5, 2.4, 0, TAU);
    ctx.fill();
  }
  if (n.id === 'elsbeth') {
    ctx.fillStyle = '#3c3630';
    ctx.beginPath();
    ctx.roundRect(-2, 5, 9, 5, 2);
    ctx.fill();
  }
  ctx.restore();

  if (dist(n.x, n.y, game.player.x, game.player.y) < 150) {
    ctx.font = '10px "Iowan Old Style", Palatino, Georgia, serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(233, 225, 207, 0.72)';
    ctx.fillText(n.name, n.x, n.y - 30);
  }
}

/* ============================================================
   ENEMIES
   ============================================================ */
export function drawEnemy(ctx, e, game) {
  if (e.dead && e.deathT > 0.7) return;
  let alpha = 1;
  if (e.fade) alpha = 1 - e.fadeT / 1.2;
  if (e.dead) alpha = 1 - e.deathT / 1.4;
  if (alpha <= 0) return;
  ctx.globalAlpha = alpha;

  const t = game.t;
  const bob = Math.sin(e.walk) * 1.2;
  const sc = (0.55 + e.spawnT * 0.45) * (e.type === 'archer' ? 0.94 : 1);
  shadow(ctx, e.x, e.y + 3, 13 * sc, 5 * sc, 0.34 * alpha);
  ctx.save();
  ctx.translate(e.x, e.y + bob * 0.5);
  ctx.rotate(e.angle);
  ctx.scale(sc, sc);
  if (e.dead) {
    ctx.rotate(0.6);
    ctx.translate(0, 4);
  }
  if (e.hurt > 0) ctx.globalAlpha = alpha * 0.75;

  // long limbs
  ctx.strokeStyle = '#141d19';
  ctx.lineWidth = 3;
  ctx.lineCap = 'round';
  const stride = Math.sin(e.walk) * 6;
  ctx.beginPath();
  ctx.moveTo(-2, -5);
  ctx.lineTo(-10 - stride, -9);
  ctx.moveTo(-2, 5);
  ctx.lineTo(-10 + stride, 9);
  ctx.moveTo(5, -6);
  ctx.lineTo(12 + (e.windup > 0 ? 6 : 0), -9);
  ctx.stroke();
  ctx.lineCap = 'butt';

  // torso
  ctx.fillStyle = e.dead ? '#242a25' : '#1b2620';
  ctx.beginPath();
  ctx.ellipse(0, 0, 12, 9.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(120, 140, 120, 0.12)';
  ctx.beginPath();
  ctx.ellipse(-1, -2, 7, 5, 0, 0, TAU);
  ctx.fill();

  // ragged cloth
  ctx.fillStyle = 'rgba(70, 62, 48, 0.55)';
  ctx.beginPath();
  ctx.moveTo(-8, -6);
  ctx.lineTo(-4, 4);
  ctx.lineTo(0, -2);
  ctx.lineTo(3, 6);
  ctx.lineTo(6, -4);
  ctx.closePath();
  ctx.fill();

  // pale head
  ctx.fillStyle = '#b6b39f';
  ctx.beginPath();
  ctx.ellipse(10, 0, 6.4, 5.4, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#252a23';
  ctx.beginPath();
  ctx.ellipse(12, 0, 3.2, 4.2, 0, 0, TAU);
  ctx.fill();

  // antlers
  ctx.strokeStyle = '#cfc7ae';
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.moveTo(10, -4);
  ctx.lineTo(14, -13);
  ctx.lineTo(18, -14);
  ctx.moveTo(13, -9);
  ctx.lineTo(17, -8);
  ctx.moveTo(10, 4);
  ctx.lineTo(14, 13);
  ctx.lineTo(18, 14);
  ctx.moveTo(13, 9);
  ctx.lineTo(17, 8);
  ctx.stroke();

  // eyes
  if (!e.dead) {
    ctx.fillStyle = 'rgba(224, 94, 70, 0.95)';
    ctx.beginPath();
    ctx.arc(13, -2, 1.1, 0, TAU);
    ctx.arc(13, 2, 1.1, 0, TAU);
    ctx.fill();
    const g = ctx.createRadialGradient(13, 0, 0, 13, 0, 11);
    g.addColorStop(0, 'rgba(224, 94, 70, 0.28)');
    g.addColorStop(1, 'rgba(224, 94, 70, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(13, 0, 11, 0, TAU);
    ctx.fill();
  }

  if (e.shield) {
    ctx.fillStyle = 'rgba(86, 70, 48, 0.95)';
    ctx.beginPath();
    ctx.arc(13, 0, 13, -1.25, 1.25);
    ctx.arc(15, 0, 13, 1.25, -1.25, true);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(210, 190, 150, 0.25)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(13, 0, 11, -1.1, 1.1);
    ctx.stroke();
  }
  if (e.archer) {
    ctx.strokeStyle = '#6b5638';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.arc(8, 10, 12, -1.2, 1.2);
    ctx.stroke();
  }
  ctx.restore();
  ctx.globalAlpha = 1;

  // attack telegraph
  if (e.windup > 0 && !e.dead) {
    ctx.strokeStyle = 'rgba(201, 79, 67, 0.42)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(e.x, e.y, 52, e.angle - 0.55, e.angle + 0.55);
    ctx.stroke();
  }

  // health + trait marks
  if (!e.dead && (e.hp < e.maxHp || e.aggro)) {
    const w = 34;
    const x = e.x - w / 2;
    const y = e.y - 46;
    ctx.fillStyle = 'rgba(6, 10, 8, 0.65)';
    ctx.fillRect(x, y, w, 3.4);
    ctx.fillStyle = 'rgba(201, 79, 67, 0.9)';
    ctx.fillRect(x, y, w * clamp(e.hp / e.maxHp, 0, 1), 3.4);
    if (e.shield || e.archer) {
      ctx.font = '9px "Iowan Old Style", Palatino, Georgia, serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(240, 176, 100, 0.8)';
      ctx.fillText(e.archer ? '➶' : '◈', e.x, y - 4);
    }
  }
}

/* ============================================================
   ANIMALS
   ============================================================ */
export function drawAnimal(ctx, a, game) {
  const t = game.t;
  const bob = Math.sin(a.bob) * (a.state === 'flee' ? 2.2 : 0.8);
  shadow(ctx, a.x, a.y + 2, a.type === 'deer' ? 12 : 6, 4, 0.24);
  ctx.save();
  ctx.translate(a.x, a.y + bob * 0.3);
  ctx.rotate(a.angle);
  if (a.type === 'deer') {
    ctx.strokeStyle = '#5c4630';
    ctx.lineWidth = 2;
    const stride = Math.sin(a.bob * 2) * 4;
    ctx.beginPath();
    ctx.moveTo(-4, -5); ctx.lineTo(-8 - stride, -8);
    ctx.moveTo(-4, 5); ctx.lineTo(-8 + stride, 8);
    ctx.moveTo(6, -5); ctx.lineTo(9 + stride, -8);
    ctx.moveTo(6, 5); ctx.lineTo(9 - stride, 8);
    ctx.stroke();
    ctx.fillStyle = '#8a6845';
    ctx.beginPath();
    ctx.ellipse(0, 0, 12, 7.4, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#9d7b55';
    ctx.beginPath();
    ctx.ellipse(11, 0, 5, 4, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#c9b98d';
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.moveTo(13, -2); ctx.lineTo(18, -9); ctx.lineTo(21, -10);
    ctx.moveTo(17, -6); ctx.lineTo(19, -2);
    ctx.moveTo(13, 2); ctx.lineTo(18, 9); ctx.lineTo(21, 10);
    ctx.stroke();
    ctx.fillStyle = '#3a2c1d';
    ctx.beginPath();
    ctx.arc(14, 0, 1.4, 0, TAU);
    ctx.fill();
  } else {
    ctx.fillStyle = '#9a8869';
    ctx.beginPath();
    ctx.ellipse(0, 0, 7, 5.4, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#a8977a';
    ctx.beginPath();
    ctx.ellipse(6, 0, 3.6, 3.4, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#a8977a';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(4, -3); ctx.lineTo(3, -9);
    ctx.moveTo(5, -3); ctx.lineTo(7, -9);
    ctx.stroke();
    ctx.fillStyle = '#2e251a';
    ctx.beginPath();
    ctx.arc(8, 0, 1, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
  if (a.hit > 0) {
    ctx.fillStyle = `rgba(201, 79, 67, ${a.hit * 2})`;
    ctx.beginPath();
    ctx.arc(a.x, a.y - 4, 12, 0, TAU);
    ctx.fill();
  }
}

export function drawCorpse(ctx, c) {
  ctx.fillStyle = 'rgba(90, 30, 26, 0.28)';
  ctx.beginPath();
  ctx.ellipse(c.x, c.y + 4, 17, 7, 0, 0, TAU);
  ctx.fill();
  ctx.save();
  ctx.translate(c.x, c.y);
  ctx.rotate(c.angle);
  ctx.fillStyle = '#6d5338';
  ctx.beginPath();
  ctx.ellipse(0, 0, c.type === 'deer' ? 13 : 7, c.type === 'deer' ? 6 : 4.5, 0, 0, TAU);
  ctx.fill();
  if (c.type === 'deer') {
    ctx.fillStyle = '#82643f';
    ctx.beginPath();
    ctx.ellipse(10, 0, 4.4, 3.4, 0, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ============================================================
   ITEMS / FX
   ============================================================ */
export function drawTrap(ctx, tr) {
  ctx.strokeStyle = tr.armed ? 'rgba(205, 195, 165, 0.8)' : 'rgba(120, 110, 92, 0.5)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.arc(tr.x, tr.y, 9, 0, TAU);
  ctx.stroke();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    ctx.beginPath();
    ctx.moveTo(tr.x + Math.cos(a) * 7, tr.y + Math.sin(a) * 5);
    ctx.lineTo(tr.x + Math.cos(a) * 11, tr.y + Math.sin(a) * 8);
    ctx.stroke();
  }
  if (tr.armed) {
    ctx.fillStyle = 'rgba(233, 225, 207, 0.7)';
    ctx.beginPath();
    ctx.arc(tr.x, tr.y, 1.6, 0, TAU);
    ctx.fill();
  }
}

export function drawArrow(ctx, pr) {
  ctx.strokeStyle = pr.from === 'player' ? 'rgba(233, 225, 207, 0.9)' : 'rgba(224, 110, 90, 0.9)';
  ctx.lineWidth = 1.6;
  const bx = pr.x - Math.cos(pr.angle) * 13;
  const by = pr.y - Math.sin(pr.angle) * 13;
  ctx.beginPath();
  ctx.moveTo(bx, by);
  ctx.lineTo(pr.x, pr.y);
  ctx.stroke();
  ctx.fillStyle = pr.from === 'player' ? '#e9e1cf' : '#e07a64';
  ctx.beginPath();
  ctx.arc(pr.x, pr.y, 1.8, 0, TAU);
  ctx.fill();
}

export function drawEcho(ctx, e, t, i) {
  const col = {
    bow: '#a9b77c', flame: '#e0763c', greed: '#b08d55', mercy: '#b9c99d',
    kill: '#c94f43', snare: '#c2a86a', shadow: '#8f9bc4', cairn: '#f0b06a',
    explore: '#8fa5b0', gather: '#9aab72', build: '#d8b46a', death: '#c94f43'
  }[e.kind] || '#d8b46a';
  const pulse = 0.55 + Math.sin(t * 1.8 + i) * 0.3;
  const glow = ctx.createRadialGradient(e.x, e.y - 4, 1, e.x, e.y - 4, 28);
  glow.addColorStop(0, rgba(col, 0.2 * pulse));
  glow.addColorStop(1, rgba(col, 0));
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(e.x, e.y - 4, 28, 0, TAU);
  ctx.fill();

  ctx.save();
  ctx.translate(e.x, e.y - 6);
  ctx.rotate(Math.PI / 4);
  ctx.strokeStyle = rgba(col, 0.5 + pulse * 0.4);
  ctx.lineWidth = 1;
  ctx.strokeRect(-4, -4, 8, 8);
  ctx.restore();

  ctx.fillStyle = rgba(col, 0.75 + pulse * 0.25);
  ctx.font = '9px "Iowan Old Style", Palatino, Georgia, serif';
  ctx.textAlign = 'center';
  ctx.fillText(glyphForKind(e.kind), e.x, e.y - 12 + Math.sin(t * 2 + i) * 2);
}

export function drawDetail(ctx, d, t) {
  switch (d.kind) {
    case 'grass': {
      const s = d.s;
      ctx.strokeStyle = 'rgba(126, 140, 92, 0.55)';
      ctx.lineWidth = 1;
      const sway = Math.sin(t * 2 + d.seed) * 1.4;
      ctx.beginPath();
      ctx.moveTo(d.x, d.y);
      ctx.quadraticCurveTo(d.x - 2 * s, d.y - 4 * s, d.x - 3 * s + sway, d.y - 7 * s);
      ctx.moveTo(d.x, d.y);
      ctx.quadraticCurveTo(d.x + 1 * s, d.y - 4 * s, d.x + 2 * s + sway, d.y - 6 * s);
      ctx.stroke();
      break;
    }
    case 'pebble':
      ctx.fillStyle = 'rgba(140, 140, 128, 0.4)';
      ctx.beginPath();
      ctx.ellipse(d.x, d.y, 2.4 * d.s, 1.6 * d.s, 0, 0, TAU);
      ctx.fill();
      break;
    case 'twig':
      ctx.strokeStyle = 'rgba(96, 84, 62, 0.45)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(d.x - 3, d.y);
      ctx.lineTo(d.x + 3, d.y - 1.5);
      ctx.stroke();
      break;
    case 'sprout':
      ctx.fillStyle = 'rgba(120, 140, 82, 0.5)';
      ctx.beginPath();
      ctx.ellipse(d.x, d.y - 1.5, 2.4, 1.2, 0.5, 0, TAU);
      ctx.fill();
      break;
    case 'lily':
      ctx.fillStyle = 'rgba(96, 128, 92, 0.42)';
      ctx.beginPath();
      ctx.ellipse(d.x, d.y, 5 * d.s, 3 * d.s, 0.3, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(220, 210, 180, 0.5)';
      ctx.beginPath();
      ctx.arc(d.x, d.y - 1, 1.1, 0, TAU);
      ctx.fill();
      break;
    default: break;
  }
}

import { TAU, clamp, rgba, lerp } from './util.js';
import {
  drawProp, drawHut, drawCairn, drawFire, drawPlayer, drawNpc, drawEnemy,
  drawAnimal, drawCorpse, drawTrap, drawArrow, drawEcho, drawDetail, drawHearthBase
} from './draw.js';

let lightCanvas = null;
let lightCtx = null;
let grainTile = null;
let grainPattern = null;
let vignetteCache = null;
let vignetteKey = '';

function ensureLight(w, h) {
  if (!lightCanvas) {
    lightCanvas = document.createElement('canvas');
    lightCtx = lightCanvas.getContext('2d');
  }
  if (lightCanvas.width !== w || lightCanvas.height !== h) {
    lightCanvas.width = w;
    lightCanvas.height = h;
  }
}

function getGrain(ctx) {
  if (!grainPattern) {
    grainTile = document.createElement('canvas');
    grainTile.width = 128;
    grainTile.height = 128;
    const g = grainTile.getContext('2d');
    for (let i = 0; i < 900; i++) {
      const a = Math.random() * 0.06;
      g.fillStyle = Math.random() < 0.5 ? `rgba(240,235,210,${a})` : `rgba(10,14,10,${a * 1.4})`;
      g.fillRect(Math.random() * 128, Math.random() * 128, 1.4, 1.4);
    }
    grainPattern = ctx.createPattern(grainTile, 'repeat');
  }
  return grainPattern;
}

export function render(ctx, game) {
  const { w, h, dpr } = game.view;
  const z = game.zoom;
  const t = game.t;
  const shakeX = (Math.random() - 0.5) * game.shake * 11;
  const shakeY = (Math.random() - 0.5) * game.shake * 11;

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#0a0f0c';
  ctx.fillRect(0, 0, w, h);

  ctx.save();
  ctx.translate(w / 2 + shakeX, h / 2 + shakeY);
  ctx.scale(z, z);
  ctx.translate(-game.camera.x, -game.camera.y);

  const halfW = w / (2 * z);
  const halfH = h / (2 * z);
  const view = {
    x1: game.camera.x - halfW - 70,
    y1: game.camera.y - halfH - 70,
    x2: game.camera.x + halfW + 70,
    y2: game.camera.y + halfH + 70
  };
  const visible = (x, y, pad = 50) =>
    x > view.x1 - pad && x < view.x2 + pad && y > view.y1 - pad && y < view.y2 + pad;

  drawGround(ctx, game, view, visible, t);
  drawPaths(ctx, game);
  drawWater(ctx, game, view, visible, t);
  for (const d of game.world.detailProps) {
    if (visible(d.x, d.y, 20)) drawDetail(ctx, d, t);
  }
  drawGroundMemory(ctx, game, t);

  /* --- y-sorted world --- */
  const list = [];
  for (const p of game.world.props) {
    if (!visible(p.x, p.y, 90)) continue;
    list.push({ y: p.y, kind: 'prop', o: p });
  }
  for (const hut of game.world.huts) {
    if (visible(hut.x, hut.y, 130)) list.push({ y: hut.y + hut.r * 0.4, kind: 'hut', o: hut });
  }
  for (const c of game.world.cairns) {
    if (visible(c.x, c.y, 160)) list.push({ y: c.y, kind: 'cairn', o: c });
  }
  for (const f of game.fires) {
    if (visible(f.x, f.y, 60)) list.push({ y: f.y, kind: 'fire', o: f });
  }
  for (const n of game.npcs) {
    if (!n.inside && visible(n.x, n.y, 60)) list.push({ y: n.y, kind: 'npc', o: n });
  }
  for (const e of game.enemies) {
    if (visible(e.x, e.y, 90)) list.push({ y: e.y, kind: 'enemy', o: e });
  }
  for (const a of game.animals) {
    if (visible(a.x, a.y, 60)) list.push({ y: a.y, kind: 'animal', o: a });
  }
  for (const c of game.corpses) {
    if (visible(c.x, c.y, 50)) list.push({ y: c.y, kind: 'corpse', o: c });
  }
  for (const tr of game.traps) {
    if (visible(tr.x, tr.y, 40)) list.push({ y: tr.y - 2, kind: 'trap', o: tr });
  }
  if (game.mode !== 'title' && !game.player.dead) {
    list.push({ y: game.player.y, kind: 'player', o: game.player });
  }
  list.sort((a, b) => a.y - b.y);

  // hearth base under fires
  for (const f of game.fires) {
    if (f.eternal && visible(f.x, f.y, 40)) drawHearthBase(ctx, f.x, f.y);
  }

  for (const item of list) {
    switch (item.kind) {
      case 'prop': drawProp(ctx, item.o, t); break;
      case 'hut': drawHut(ctx, item.o, t, game.nightLevel()); break;
      case 'cairn': drawCairn(ctx, item.o, t); break;
      case 'fire': drawFire(ctx, item.o, t); break;
      case 'npc': drawNpc(ctx, item.o, game); break;
      case 'enemy': drawEnemy(ctx, item.o, game); break;
      case 'animal': drawAnimal(ctx, item.o, game); break;
      case 'corpse': drawCorpse(ctx, item.o); break;
      case 'trap': drawTrap(ctx, item.o); break;
      case 'player': drawPlayer(ctx, game.player, game); break;
      default: break;
    }
  }

  // arrows above the ground clutter
  for (const pr of game.projectiles) {
    if (visible(pr.x, pr.y, 40)) drawArrow(ctx, pr);
  }

  // ember ring
  if (game.emberRing) {
    const ring = game.emberRing;
    ring.t -= 1 / 60;
    if (ring.t <= 0) game.emberRing = null;
    else {
      const p = 1 - ring.t / ring.max;
      ctx.strokeStyle = `rgba(240, 160, 90, ${0.5 * (1 - p)})`;
      ctx.lineWidth = 3 * (1 - p) + 1;
      ctx.beginPath();
      ctx.arc(ring.x, ring.y, 40 + p * 150, 0, TAU);
      ctx.stroke();
    }
  }

  // particles
  for (const p of game.particles) {
    if (!visible(p.x, p.y, 30)) continue;
    const a = clamp(p.life / p.maxLife, 0, 1);
    ctx.globalAlpha = p.kind === 'smoke' ? a * 0.35 : a;
    ctx.fillStyle = p.color;
    if (p.kind === 'ember' || p.kind === 'spark') {
      ctx.globalCompositeOperation = 'lighter';
    }
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * (p.kind === 'smoke' ? 1 + (1 - a) * 1.2 : 1), 0, TAU);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }
  ctx.globalAlpha = 1;

  // interaction marker
  if (game.currentInteract && game.mode === 'play') {
    const it = game.currentInteract;
    const pulse = 0.55 + Math.sin(t * 3.4) * 0.22;
    ctx.strokeStyle = `rgba(233, 225, 207, ${pulse * 0.5})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(it.x, it.y - 8, 16, 0, TAU);
    ctx.stroke();
  }

  ctx.restore();

  /* --- screen-space light & weather --- */
  drawLighting(ctx, game, shakeX, shakeY, t);

  // beam and memory glow above the dark
  ctx.save();
  ctx.translate(w / 2 + shakeX, h / 2 + shakeY);
  ctx.scale(z, z);
  ctx.translate(-game.camera.x, -game.camera.y);
  for (const c of game.world.cairns) {
    if (c.lit && visibleStatic(c.x, c.y, game, w, h, z, 260)) drawBeam(ctx, c, t);
  }
  game.echoes.forEach((e, i) => {
    if (e.x != null && visibleStatic(e.x, e.y, game, w, h, z, 60)) drawEcho(ctx, e, t, i);
  });
  for (const f of game.floaters) {
    const a = clamp(f.life / f.maxLife, 0, 1);
    ctx.globalAlpha = a;
    ctx.font = `600 ${f.size}px "Iowan Old Style", Palatino, Georgia, serif`;
    ctx.textAlign = 'center';
    ctx.fillStyle = f.color;
    ctx.shadowColor = 'rgba(0,0,0,0.7)';
    ctx.shadowBlur = 4;
    ctx.fillText(f.text, f.x, f.y);
    ctx.shadowBlur = 0;
  }
  ctx.globalAlpha = 1;
  ctx.restore();

  drawWeather(ctx, game, t, w, h);
  drawVignette(ctx, game, w, h, shakeX, shakeY);
}

function visibleStatic(x, y, game, w, h, z, pad = 0) {
  const dx = Math.abs(x - game.camera.x) * z;
  const dy = Math.abs(y - game.camera.y) * z;
  return dx < w / 2 + pad && dy < h / 2 + pad;
}

/* ============================================================
   GROUND
   ============================================================ */
function drawGround(ctx, game, view, visible, t) {
  const world = game.world;
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(world.groundCanvas, 0, 0, world.w, world.h);

  // village worn earth
  const v = world.village;
  if (visible(v.x, v.y, 400)) {
    const g = ctx.createRadialGradient(v.x, v.y, 40, v.x, v.y, 330);
    g.addColorStop(0, 'rgba(130, 110, 76, 0.36)');
    g.addColorStop(0.6, 'rgba(130, 110, 76, 0.14)');
    g.addColorStop(1, 'rgba(130, 110, 76, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(v.x, v.y, 330, 0, TAU);
    ctx.fill();
  }

  // subtle painterly grain
  const pat = getGrain(ctx);
  if (pat) {
    ctx.save();
    ctx.globalAlpha = 0.55;
    ctx.fillStyle = pat;
    ctx.fillRect(view.x1, view.y1, view.x2 - view.x1, view.y2 - view.y1);
    ctx.restore();
  }

  // faint biome light pools for depth
  const patches = [
    [world.lake.x, world.lake.y, 520, 'rgba(80, 130, 140, 0.05)'],
    [world.bog.x, world.bog.y, 460, 'rgba(60, 90, 70, 0.06)'],
    [world.ruins.x, world.ruins.y, 260, 'rgba(180, 190, 180, 0.035)']
  ];
  for (const [x, y, r, col] of patches) {
    if (!visible(x, y, r)) continue;
    const g = ctx.createRadialGradient(x, y, 10, x, y, r);
    g.addColorStop(0, col);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
}

function drawPaths(ctx, game) {
  const paths = game.world.paths;
  for (const path of paths) {
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = 'rgba(99, 83, 58, 0.34)';
    ctx.lineWidth = 34;
    strokePoints(ctx, path.points);
    ctx.strokeStyle = 'rgba(124, 106, 74, 0.32)';
    ctx.lineWidth = 20;
    strokePoints(ctx, path.points);
    ctx.strokeStyle = 'rgba(154, 136, 98, 0.13)';
    ctx.lineWidth = 3;
    ctx.setLineDash([2, 15]);
    strokePoints(ctx, path.points);
    ctx.setLineDash([]);
    ctx.lineCap = 'butt';
  }
}

function strokePoints(ctx, pts) {
  ctx.beginPath();
  pts.forEach((p, i) => {
    if (i === 0) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  });
  ctx.stroke();
}

function drawWater(ctx, game, view, visible, t) {
  if (!game.world._waterCells) {
    const cells = [];
    const step = 90;
    for (let y = 0; y < game.world.h; y += step) {
      for (let x = 0; x < game.world.w; x += step) {
        if (game.world.waterAt(x, y)) cells.push({ x, y, seed: (x * 13 + y * 7) % 100 });
      }
    }
    game.world._waterCells = cells;
  }
  ctx.strokeStyle = 'rgba(190, 220, 220, 0.18)';
  ctx.lineWidth = 1.2;
  for (const c of game.world._waterCells) {
    if (!visible(c.x, c.y, 20)) continue;
    const wob = Math.sin(t * 1.3 + c.seed) * 4;
    ctx.beginPath();
    ctx.moveTo(c.x - 9 + wob, c.y + Math.sin(t + c.seed) * 1.5);
    ctx.lineTo(c.x + 9 + wob, c.y + Math.sin(t + c.seed) * 1.5);
    ctx.stroke();
  }
}

/* ============================================================
   WORLD MEMORY
   ============================================================ */
function drawGroundMemory(ctx, game, t) {
  const memory = game.world._campScars;
  if (memory) {
    for (const s of memory) {
      ctx.fillStyle = 'rgba(24, 20, 16, 0.22)';
      ctx.beginPath();
      ctx.ellipse(s.x, s.y, 34, 18, 0, 0, TAU);
      ctx.fill();
    }
  }
  // recent campfire scars are drawn from the fires list, including dead ones
}

function drawBeam(ctx, c, t) {
  const flick = 0.7 + Math.sin(t * 2.2 + c.x) * 0.14;
  const g = ctx.createLinearGradient(0, c.y - 440, 0, c.y - 20);
  g.addColorStop(0, 'rgba(240, 170, 90, 0)');
  g.addColorStop(0.55, `rgba(240, 160, 86, ${0.1 * flick})`);
  g.addColorStop(1, `rgba(255, 190, 120, ${0.2 * flick})`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(c.x - 8, c.y - 20);
  ctx.lineTo(c.x - 30, c.y - 440);
  ctx.lineTo(c.x + 30, c.y - 440);
  ctx.lineTo(c.x + 8, c.y - 20);
  ctx.closePath();
  ctx.fill();
}

/* ============================================================
   LIGHTING
   ============================================================ */
function drawLighting(ctx, game, shakeX, shakeY, t) {
  const { w, h } = game.view;
  const dark = game.centerDarkness();
  if (dark <= 0.02) return;
  ensureLight(w, h);
  const l = lightCtx;
  l.setTransform(1, 0, 0, 1, 0, 0);
  l.clearRect(0, 0, w, h);
  l.fillStyle = `rgba(5, 9, 15, ${clamp(dark, 0, 0.86)})`;
  l.fillRect(0, 0, w, h);

  const z = game.zoom;
  const sx = (x) => (x - game.camera.x) * z + w / 2 + shakeX;
  const sy = (y) => (y - game.camera.y) * z + h / 2 + shakeY;

  l.globalCompositeOperation = 'destination-out';
  const hole = (x, y, radius, strength = 1) => {
    const g = l.createRadialGradient(x, y, radius * 0.05, x, y, radius);
    g.addColorStop(0, `rgba(0,0,0,${strength})`);
    g.addColorStop(0.42, `rgba(0,0,0,${strength * 0.82})`);
    g.addColorStop(0.72, `rgba(0,0,0,${strength * 0.34})`);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    l.fillStyle = g;
    l.fillRect(x - radius, y - radius, radius * 2, radius * 2);
  };

  const p = game.player;
  hole(sx(p.x), sy(p.y), 150 * z, 0.55);
  for (const f of game.fires) {
    const flick = 1 + Math.sin(t * 7 + f.seed) * 0.05 + Math.sin(t * 11.7 + f.seed) * 0.03;
    hole(sx(f.x), sy(f.y), f.light * z * flick, f.eternal ? 1 : 0.95);
  }
  for (const c of game.world.cairns) {
    if (c.lit) hole(sx(c.x), sy(c.y), 315 * z, 0.9);
  }
  if (dark > 0.2) {
    for (const lantern of game.world.lanterns) {
      hole(sx(lantern.x), sy(lantern.y), lantern.r * z, 0.6);
    }
  }
  l.globalCompositeOperation = 'source-over';
  ctx.drawImage(lightCanvas, 0, 0);

  // warm glow on top
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const f of game.fires) {
    const flick = 0.9 + Math.sin(t * 6 + f.seed) * 0.1;
    const x = sx(f.x), y = sy(f.y);
    const g = ctx.createRadialGradient(x, y, 2, x, y, f.light * z * 0.7);
    g.addColorStop(0, `rgba(240, 150, 80, ${0.16 * flick})`);
    g.addColorStop(0.4, `rgba(224, 118, 60, ${0.06 * flick})`);
    g.addColorStop(1, 'rgba(224, 118, 60, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - f.light * z, y - f.light * z, f.light * z * 2, f.light * z * 2);
  }
  for (const c of game.world.cairns) {
    if (!c.lit) continue;
    const x = sx(c.x), y = sy(c.y);
    const g = ctx.createRadialGradient(x, y, 2, x, y, 320 * z);
    g.addColorStop(0, 'rgba(240, 170, 90, 0.14)');
    g.addColorStop(1, 'rgba(240, 170, 90, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - 320 * z, y - 320 * z, 640 * z, 640 * z);
  }
  ctx.restore();
}

/* ============================================================
   WEATHER / VIGNETTE
   ============================================================ */
function drawWeather(ctx, game, t, w, h) {
  if (game.weather.type === 'rain' && game.mode !== 'title') {
    ctx.save();
    ctx.strokeStyle = 'rgba(170, 195, 200, 0.19)';
    ctx.lineWidth = 1;
    const drift = t * 420;
    for (let i = 0; i < 130; i++) {
      const x = ((i * 97.3 + drift * 0.7) % (w + 120)) - 60;
      const y = ((i * 53.7 + drift) % (h + 120)) - 60;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - 4, y + 15);
      ctx.stroke();
    }
    ctx.restore();
    ctx.fillStyle = 'rgba(30, 50, 52, 0.05)';
    ctx.fillRect(0, 0, w, h);
  }
  if (game.weather.type === 'fog') {
    ctx.save();
    ctx.fillStyle = 'rgba(160, 172, 170, 0.045)';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 4; i++) {
      const x = ((i * 420 + t * 12) % (w + 500)) - 250;
      const y = h * (0.28 + i * 0.16) + Math.sin(t * 0.2 + i) * 20;
      const g = ctx.createRadialGradient(x, y, 0, x, y, 320);
      g.addColorStop(0, 'rgba(180, 192, 190, 0.05)');
      g.addColorStop(1, 'rgba(180, 192, 190, 0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - 320, y - 320, 640, 640);
    }
    ctx.restore();
  }
  if (game.weather.type === 'clear' && game.nightLevel() > 0.4 && game.mode !== 'title') {
    // fireflies
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 16; i++) {
      const x = ((i * 211.7 + t * (9 + i % 5)) % (w + 80)) - 40;
      const y = ((i * 137.3 + Math.sin(t * 0.7 + i) * 40) % (h + 80)) - 40;
      const a = 0.18 + Math.sin(t * 2.4 + i * 1.7) * 0.14;
      ctx.fillStyle = `rgba(206, 220, 140, ${Math.max(0, a)})`;
      ctx.beginPath();
      ctx.arc(x, y, 1.5, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }
  if (game.nightLevel() > 0.35) {
    ctx.fillStyle = `rgba(20, 34, 54, ${game.nightLevel() * 0.045})`;
    ctx.fillRect(0, 0, w, h);
  }
}

function drawVignette(ctx, game, w, h, shakeX, shakeY) {
  const key = `${w}x${h}`;
  if (vignetteKey !== key) {
    vignetteCache = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.26, w / 2, h / 2, Math.max(w, h) * 0.78);
    vignetteCache.addColorStop(0, 'rgba(3, 6, 5, 0)');
    vignetteCache.addColorStop(0.65, 'rgba(3, 6, 5, 0.12)');
    vignetteCache.addColorStop(1, 'rgba(3, 6, 5, 0.62)');
    vignetteKey = key;
  }
  ctx.fillStyle = vignetteCache;
  ctx.fillRect(0, 0, w, h);

  if (game.damageFlash > 0.01) {
    const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.62);
    g.addColorStop(0, 'rgba(120, 24, 18, 0)');
    g.addColorStop(1, `rgba(120, 24, 18, ${game.damageFlash * 0.5})`);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }

  if (game.phaseKey() === 'dusk' || game.phaseKey() === 'dawn') {
    ctx.fillStyle = 'rgba(224, 138, 68, 0.035)';
    ctx.fillRect(0, 0, w, h);
  }

  // letterbox grain at screen edges
  const g2 = ctx.createLinearGradient(0, 0, 0, h);
  g2.addColorStop(0, 'rgba(3, 6, 5, 0.28)');
  g2.addColorStop(0.14, 'rgba(3, 6, 5, 0)');
  g2.addColorStop(0.86, 'rgba(3, 6, 5, 0)');
  g2.addColorStop(1, 'rgba(3, 6, 5, 0.34)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, w, h);
}

/* ============================================================
   MINIMAP
   ============================================================ */
export function drawMinimap(canvas, game) {
  const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;
  const world = game.world;
  ctx.clearRect(0, 0, w, h);
  ctx.drawImage(world.minimap, 0, 0, w, h);

  const mx = (x) => (x / world.w) * w;
  const my = (y) => (y / world.h) * h;

  // village
  ctx.fillStyle = 'rgba(233, 225, 207, 0.65)';
  ctx.beginPath();
  ctx.arc(mx(world.village.x), my(world.village.y), 2.6, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(233, 225, 207, 0.28)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.arc(mx(world.village.x), my(world.village.y), 5, 0, TAU);
  ctx.stroke();

  // cairns
  for (const c of world.cairns) {
    const x = mx(c.x), y = my(c.y);
    if (c.lit) {
      ctx.fillStyle = 'rgba(240, 160, 86, 0.95)';
      ctx.beginPath();
      ctx.arc(x, y, 2.6, 0, TAU);
      ctx.fill();
      const g = ctx.createRadialGradient(x, y, 0, x, y, 8);
      g.addColorStop(0, 'rgba(240, 160, 86, 0.45)');
      g.addColorStop(1, 'rgba(240, 160, 86, 0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - 8, y - 8, 16, 16);
    } else {
      ctx.strokeStyle = 'rgba(233, 225, 207, 0.6)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y - 3.5);
      ctx.lineTo(x + 2.8, y + 2);
      ctx.lineTo(x - 2.8, y + 2);
      ctx.closePath();
      ctx.stroke();
    }
  }

  // ruins
  ctx.fillStyle = 'rgba(200, 205, 195, 0.35)';
  ctx.fillRect(mx(world.ruins.x) - 2, my(world.ruins.y) - 2, 4, 4);

  // memory echoes
  for (const e of game.echoes) {
    if (e.x == null) continue;
    ctx.fillStyle = 'rgba(216, 180, 106, 0.4)';
    ctx.beginPath();
    ctx.arc(mx(e.x), my(e.y), 1, 0, TAU);
    ctx.fill();
  }

  // enemies
  for (const e of game.enemies) {
    if (e.dead || e.fade) continue;
    ctx.fillStyle = 'rgba(212, 90, 74, 0.85)';
    ctx.beginPath();
    ctx.arc(mx(e.x), my(e.y), 1.7, 0, TAU);
    ctx.fill();
  }

  // player arrow
  const px = mx(game.player.x), py = my(game.player.y);
  ctx.save();
  ctx.translate(px, py);
  ctx.rotate(game.player.angle);
  ctx.fillStyle = 'rgba(245, 238, 218, 0.95)';
  ctx.beginPath();
  ctx.moveTo(5, 0);
  ctx.lineTo(-3.4, 3.2);
  ctx.lineTo(-1.6, 0);
  ctx.lineTo(-3.4, -3.2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // night wash
  const night = game.nightLevel();
  if (night > 0) {
    ctx.fillStyle = `rgba(10, 16, 24, ${night * 0.24})`;
    ctx.fillRect(0, 0, w, h);
  }
  // frame
  ctx.strokeStyle = 'rgba(233, 225, 207, 0.1)';
  ctx.lineWidth = 1;
  ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
}

