401: function buildGroundCanvas(biomeAt, noise) {
402:   const scale = 0.16;
403:   const w = Math.ceil(WORLD_W * scale);
404:   const h = Math.ceil(WORLD_H * scale);
405:   const canvas = document.createElement('canvas');
406:   canvas.width = w;
407:   canvas.height = h;
408:   const ctx = canvas.getContext('2d');
409:   const img = ctx.createImageData(w, h);
410:   const cache = new Map();
411:   for (let py = 0; py < h; py++) {
412:     for (let px = 0; px < w; px++) {
413:       const wx = px / scale, wy = py / scale;
414:       const biome = biomeAt(wx, wy);
415:       let palette = BIOME[biome];
416:       if (!palette) palette = BIOME.meadow;
417:       const v = noise.value(px * 0.44, py * 0.44);
418:       const idx = Math.min(2, Math.floor(v * 3));
419:       const hex = palette.shades[idx];
420:       const n = parseInt(hex.slice(1), 16);
421:       const i = (py * w + px) * 4;
422:       img.data[i] = (n >> 16) & 255;
423:       img.data[i + 1] = (n >> 8) & 255;
424:       img.data[i + 2] = n & 255;
425:       img.data[i + 3] = 255;
426:     }
427:   }
428:   ctx.putImageData(img, 0, 0);
429:   return canvas;
430: }
