432: function buildMinimap(biomeAt, paths) {
433:   const w = 184, h = 136;
434:   const canvas = document.createElement('canvas');
435:   canvas.width = w;
436:   canvas.height = h;
437:   const ctx = canvas.getContext('2d');
438:   for (let y = 0; y < h; y++) {
439:     for (let x = 0; x < w; x++) {
440:       const wx = (x / w) * WORLD_W, wy = (y / h) * WORLD_H;
441:       const b = biomeAt(wx, wy);
442:       ctx.fillStyle = BIOME[b] ? BIOME[b].base : '#5a6742';
443:       ctx.fillRect(x, y, 1, 1);
444:     }
445:   }
446:   ctx.strokeStyle = 'rgba(216, 180, 106, 0.32)';
447:   ctx.lineWidth = 1.2;
448:   for (const path of paths) {
449:     ctx.beginPath();
450:     path.points.forEach((p, i) => {
451:       const x = (p.x / WORLD_W) * w, y = (p.y / WORLD_H) * h;
452:       if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
453:     });
454:     ctx.stroke();
455:   }
456:   return canvas;
457: }
