459: /** Resolve a circle against the world's solid colliders. Mutates and returns {x,y}. */
460: export function resolveCollisions(world, x, y, radius) {
461:   const cells = 1;
462:   let px = x, py = y;
463:   for (let pass = 0; pass < 2; pass++) {
464:     const cx = Math.floor(px / world.colCell), cy = Math.floor(py / world.colCell);
465:     for (let gx = cx - cells; gx <= cx + cells; gx++) {
466:       for (let gy = cy - cells; gy <= cy + cells; gy++) {
467:         const list = world.colGrid.get(`${gx},${gy}`);
468:         if (!list) continue;
469:         for (const c of list) {
470:           if (c.prop && (c.prop.done || c.prop.kind === 'garden' || c.prop.kind === 'lantern')) continue;
471:           const dx = px - c.x, dy = py - c.y;
472:           const rr = radius + c.r;
473:           const d2 = dx * dx + dy * dy;
474:           if (d2 >= rr * rr) continue;
475:           const d = Math.sqrt(d2) || 0.001;
476:           px += (dx / d) * (rr - d);
477:           py += (dy / d) * (rr - d);
478:         }
479:       }
480:     }
481:   }
482:   return {
483:     x: clamp(px, 24, world.w - 24),
484:     y: clamp(py, 24, world.h - 24)
485:   };
486: }
