488: export function hasLineOfSight(world, x1, y1, x2, y2) {
489:   const steps = Math.ceil(Math.hypot(x2 - x1, y2 - y1) / 26);
490:   for (let i = 1; i < steps; i++) {
491:     const t = i / steps;
492:     const x = lerp(x1, x2, t), y = lerp(y1, y2, t);
493:     const cx = Math.floor(x / world.colCell), cy = Math.floor(y / world.colCell);
494:     for (let gx = cx - 0; gx <= cx; gx++) {
495:       for (let gy = cy - 0; gy <= cy; gy++) {
496:         const list = world.colGrid.get(`${gx},${gy}`);
497:         if (!list) continue;
498:         for (const c of list) {
499:           if (!c.prop || c.prop.done) continue;
500:           if (c.prop.kind === 'lantern' || c.prop.kind === 'bush' || c.prop.kind === 'garden') continue;
501:           if ((x - c.x) ** 2 + (y - c.y) ** 2 < (c.r + 4) ** 2) return false;
502:         }
503:       }
504:     }
505:   }
506:   return true;
507: }
