const { createRequire } = require('node:module');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const fs = require('fs');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.stack || e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/shots/title.png' });
  await page.click('#playBtn');
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => {
    const g = window.hollowmoor.game;
    const cam = g.camera;
    const view = { x1: cam.x - g.view.w / (2 * g.zoom), x2: cam.x + g.view.w / (2 * g.zoom), y1: cam.y - g.view.h / (2 * g.zoom), y2: cam.y + g.view.h / (2 * g.zoom) };
    const inView = g.world.props.filter(p => p.x > view.x1 && p.x < view.x2 && p.y > view.y1 && p.y < view.y2);
    const kinds = {};
    for (const p of inView) kinds[p.kind] = (kinds[p.kind] || 0) + 1;
    const allKinds = {};
    for (const p of g.world.props) allKinds[p.kind] = (allKinds[p.kind] || 0) + 1;
    return {
      mode: g.mode, player: { x: g.player.x, y: g.player.y }, camera: cam, zoom: g.zoom,
      view, totalProps: g.world.props.length, inView: inView.length, kinds, allKinds,
      viewport: g.view, minimap: { w: g.world.minimap.width, h: g.world.minimap.height },
      ground: { w: g.world.groundCanvas.width, h: g.world.groundCanvas.height }
    };
  });
  console.log(JSON.stringify(info, null, 2));
  console.log('ERRORS', errors);
  await page.screenshot({ path: '/tmp/opencode/shots/play.png' });
  await browser.close();
})();

