    if (kind === 'smoke') { color = opts.color || 'rgba(80,86,78,0.4)'; size = rng.range(3, 7); life = rng.range(1.2, 2.4); g = -16; sp = rng.range(4, 14); }
    if (kind === 'soul') { color = opts.color || '#c8d0da'; size = rng.range(1.4, 3); life = rng.range(0.8, 1.6); g = -20; }
