import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
for (let i = 0; i < 10; i++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  const candidate = page.locator('button, input[type="button"], input[type="submit"], [role="button"]');
  const matches = [];
  for (const control of await candidate.all()) {
    if (!await control.isVisible() || !await control.isEnabled()) continue;
    const eligible = await control.evaluate((element, explicit) => {
      if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false;
      if (explicit) return true;
      const label = element.getAttribute('aria-label') || element.value || element.textContent || '';
      return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim());
    }, false);
    if (eligible) matches.push(control);
  }
  let out = { n: matches.length };
  if (matches.length === 1) {
    const t = Date.now();
    try { await matches[0].click({ trial: true, timeout: 2000 }); out.trial = 'ok'; }
    catch (e) { out.trial = e.name; out.detail = e.message.split('\n').filter(l => /waiting|intercepts|stable|visible|enabled/.test(l)).join(' | '); }
    out.ms = Date.now() - t;
    const at = await page.evaluate(() => { const r = document.getElementById('playBtn').getBoundingClientRect(); const e = document.elementFromPoint(r.x + r.width/2, r.y+r.height/2); return e ? e.tagName + '#' + e.id + '.' + e.className : null; });
    out.at = at;
  }
  console.log(i, JSON.stringify(out));
  await page.close();
}
await browser.close();

