const runtimeRoot = '/home/runner/work/_temp/omgithub-runtime/scripts';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const captures = require2(join(runtimeRoot, 'wip-screenshots.cjs'));
captures.instrument({ chromium });
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
for (let i = 0; i < 10; i++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const failures = [];
  page.on('pageerror', e => { console.error('PAGEERR', e.message); failures.push(e.message); });
  const t0 = Date.now();
  const response = await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 });
  await page.locator('body').waitFor({ state: 'visible' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  const t1 = Date.now();
  const candidate = page.locator('button, input[type="button"], input[type="submit"], [role="button"]');
  const matches = [];
  for (const control of await candidate.all()) {
    if (!await control.isVisible() || !await control.isEnabled()) continue;
    const eligible = await control.evaluate((element) => {
      if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false;
      const label = element.getAttribute('aria-label') || element.value || element.textContent || '';
      return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim());
    });
    if (eligible) matches.push(control);
  }
  let trial = 'none';
  let detail = '';
  if (matches.length === 1) {
    try { await matches[0].click({ trial: true, timeout: 2000 }); trial = 'ok'; }
    catch (e) { trial = e.name; detail = e.message.split('\n').filter(l => /waiting|intercepts|stable|visible|enabled/.test(l)).join(' | '); }
  }
  console.log(i, 'load', t1 - t0, 'trial', Date.now() - t1, trial, matches.length, detail);
  await page.close();
}
await browser.close();

