import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.stack || e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.click('#playBtn');
await page.waitForTimeout(400);

const state = () => page.evaluate(() => {
  const g = window.hollowmoor.game;
  return {
    mode: g.mode, x: g.player.x, y: g.player.y,
    hp: g.player.hp, berries: g.player.berry, wood: g.player.wood, stone: g.player.stone,
    torches: g.player.torches, meat: g.player.meat, cooked: g.player.cooked,
    kills: g.chronicle.traits.kills, unlocked: [...g.chronicle.unlocked], cycle: g.chronicle.cycle,
    events: g.chronicle.events.length, lit: g.world.cairns.map(c => c.lit),
    hud: !document.getElementById('hud').classList.contains('hidden'),
    title: !document.getElementById('title').classList.contains('hidden'),
    ledger: !document.getElementById('ledger').classList.contains('hidden'),
    craft: !document.getElementById('craft').classList.contains('hidden'),
    death: !document.getElementById('death').classList.contains('hidden'),
    ending: !document.getElementById('ending').classList.contains('hidden'),
    toast: document.querySelector('.toast')?.textContent || null
  };
});

console.log('start', await state());

// movement
const before = await state();
await page.keyboard.down('KeyD');
await page.waitForTimeout(500);
await page.keyboard.up('KeyD');
const after = await state();
console.log('moved dx', Math.round(after.x - before.x), 'dy', Math.round(after.y - before.y));

// attack a nearby tree via teleport
await page.evaluate(() => {
  const g = window.hollowmoor.game;
  const tree = g.world.props.find(p => p.kind === 'pine' && !p.done);
  g.player.x = tree.x + 38; g.player.y = tree.y;
  g.camera.x = g.player.x; g.camera.y = g.player.y;
  window.__tree = tree;
});
await page.waitForTimeout(150);
const woodBefore = (await state()).wood;
