const { chromium } = require2('playwright');
const browser = await chromium.launch({ headless: true });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => errors.push(e.stack || e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.click('#playBtn');
await page.waitForTimeout(400);

const snap = () => page.evaluate(() => { const g = window.hollowmoor.game; return { mode: g.mode, wood: g.player.wood, fiber: g.player.fiber, torches: g.player.torches, arrows: g.player.arrows, toast: document.querySelector('.toast')?.textContent }; });
console.log('before craft', await snap());
await page.keyboard.press('KeyC');
await page.waitForTimeout(200);
await page.click('button[data-recipe="torch"]');
await page.waitForTimeout(300);
console.log('after torch craft', await snap());
await page.click('button[data-recipe="arrows"]');
await page.waitForTimeout(300);
console.log('after arrows craft', await snap());
await page.screenshot({ path: '/tmp/opencode/shots/craft-after.png' });
await page.keyboard.press('Escape');
console.log('mode after close', (await snap()).mode);

// combat: spawn an enemy and hit it
await page.evaluate(async () => {
  const { spawnEnemy } = await import('./js/combat.js');
  const g = window.hollowmoor.game;
  g.player.tool = 0;
  g.player.angle = 0;
  const e = spawnEnemy(g, { x: g.player.x + 40, y: g.player.y, aggro: false });
  window.__enemy = e;
  window.__enemyHp = e.hp;
});
await page.waitForTimeout(100);
const e0 = await page.evaluate(() => ({ hp: window.__enemy.hp, max: window.__enemy.maxHp }));
for (let i = 0; i < 6; i++) { await page.mouse.click(720, 450); await page.waitForTimeout(520); }
const e1 = await page.evaluate(() => { const g = window.hollowmoor.game; return { hp: window.__enemy.hp, dead: window.__enemy.dead, kills: g.chronicle.traits.kills, events: g.chronicle.events.length }; });
console.log('enemy', e0, '->', e1);

// adaptation hostile check via a bow kill
await page.evaluate(async () => {
  const { spawnEnemy, damageEnemy } = await import('./js/combat.js');
  const g = window.hollowmoor.game;
  for (let i = 0; i < 7; i++) {
    const e = spawnEnemy(g, { x: g.player.x + 80, y: g.player.y, aggro: false });
    damageEnemy(g, e, 999, 'arrow');
  }
});
await page.waitForTimeout(500);
console.log('unlocks after 7 bow-ish kills', await page.evaluate(() => ({ unlocked: window.hollowmoor.game.chronicle.unlocked, bow: window.hollowmoor.game.chronicle.traits.bow })));

// mobile touch
const m = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const mErrors = [];
m.on('pageerror', e => mErrors.push(e.stack || e.message));
m.on('console', msg => { if (msg.type() === 'error') mErrors.push('console: ' + msg.text()); });
await m.goto('http://localhost:3002/', { waitUntil: 'load' });
await m.click('#playBtn');
await m.waitForTimeout(500);
const touchState = await m.evaluate(() => { const g = window.hollowmoor.game; return { mode: g.mode, isTouch: g.isTouch, touchVisible: !document.getElementById('touch').classList.contains('hidden'), hotbar: getComputedStyle(document.getElementById('hotbar')).display }; });
console.log('touch state', touchState);
const p0 = await m.evaluate(() => ({ x: window.hollowmoor.game.player.x, y: window.hollowmoor.game.player.y }));
// drag the virtual stick
const stick = await m.locator('#stick').boundingBox();
if (stick) {
  const cx = stick.x + stick.width / 2, cy = stick.y + stick.height / 2;
  await m.mouse.move(cx, cy);
  await m.mouse.down();
  await m.mouse.move(cx + 30, cy - 20, { steps: 5 });
  await m.waitForTimeout(700);
  await m.mouse.up();
}
const p1 = await m.evaluate(() => ({ x: window.hollowmoor.game.player.x, y: window.hollowmoor.game.player.y }));
console.log('stick moved', Math.round(p1.x - p0.x), Math.round(p1.y - p0.y));
