await m.tap('#btnAttack');
await m.waitForTimeout(250);
console.log('attack anim', await m.evaluate(() => window.hollowmoor.game.player.atkAnim));
await m.screenshot({ path: '/tmp/opencode/shots/mobile-play.png' });
