import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.stack || e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.click('#playBtn');
await page.waitForTimeout(300);
await page.evaluate(async () => {
  const { spawnEnemy } = await import('./js/combat.js');
  const g = window.hollowmoor.game;
  g.time.minutes = 23 * 60;
  g.player.x = g.world.village.x + 550;
  g.player.y = g.world.village.y + 120;
  g.camera.x = g.player.x; g.camera.y = g.player.y;
  g.player.hp = 100;
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2;
    spawnEnemy(g, { x: g.player.x + Math.cos(a) * 170, y: g.player.y + Math.sin(a) * 170, aggro: true });
  }
});
await page.waitForTimeout(600);
console.log('night start', await page.evaluate(() => { const g = window.hollowmoor.game; return { hp: g.player.hp, enemies: g.enemies.length, night: g.nightLevel(), mode: g.mode, prototype: g.chronicle.mods() }; }));
// fight: aim at nearest and swing, dodge, ember, trap
for (let i = 0; i < 14; i++) {
  await page.evaluate(() => {
    const g = window.hollowmoor.game;
    const e = g.enemies.filter(x => !x.dead).sort((a,b) => Math.hypot(a.x-g.player.x,a.y-g.player.y)-Math.hypot(b.x-g.player.x,b.y-g.player.y))[0];
    if (e) { g.mouse.x = g.view.w/2 + (e.x-g.player.x)*g.zoom; g.mouse.y = g.view.h/2 + (e.y-g.player.y)*g.zoom; g.player.angle = Math.atan2(e.y-g.player.y,e.x-g.player.x); }
  });
  await page.mouse.click(720, 450);
  await page.waitForTimeout(300);
  if (i % 4 === 1) await page.keyboard.press('Space');
  if (i % 5 === 2) await page.keyboard.press('KeyF');
  if (i % 6 === 3) await page.keyboard.press('KeyQ');
}
await page.waitForTimeout(500);
const mid = await page.evaluate(() => { const g = window.hollowmoor.game; return { hp: Math.round(g.player.hp), stam: Math.round(g.player.stamina), enemies: g.enemies.length, dead: g.player.dead, mode: g.mode, kills: g.chronicle.traits.kills, escaped: g.chronicle.traits.escapes, traps: g.traps.length, toast: document.querySelector('.toast')?.textContent }; });
console.log('after fight', mid);
await page.screenshot({ path: '/tmp/opencode/shots/fight.png' });
await page.waitForTimeout(6000);
console.log('after 6s night', await page.evaluate(() => { const g = window.hollowmoor.game; return { hp: Math.round(g.player.hp), mode: g.mode, enemies: g.enemies.length, day: g.time.day, phase: g.phaseKey() }; }));
console.log('errors', errors);
await browser.close();

