@media (max-width: 820px), (max-height: 520px) and (pointer: coarse) {
  .hud-top {
    top: calc(10px + var(--safe-top));
    left: calc(12px + var(--safe-left));
    right: calc(12px + var(--safe-right));
    gap: 8px;
  }
  .brand { min-width: 0; gap: 8px; }
  .brand-mark { width: 27px; height: 27px; font-size: 16px; }
  .brand-name { font-size: 10.5px; letter-spacing: .2em; }
  .brand-cycle { font-size: 6.5px; letter-spacing: .18em; }
  .clockbox { min-width: 0; }
  .clock { font-size: 11px; letter-spacing: .08em; }
  .phase { font-size: 6.5px; letter-spacing: .2em; }

  .objective {
    position: absolute;
    top: calc(48px + var(--safe-top));
    left: 50%;
    transform: translateX(-50%);
    padding: 5px 12px 6px;
    white-space: nowrap;
  }
  .obj-eyebrow { font-size: 6px; letter-spacing: .22em; margin-bottom: 2px; }
  #objText { font-size: 10.5px; }
  .obj-row { gap: 7px; }
  .pips { gap: 3px; }
  .pips i { width: 6px; height: 6px; }

  .vitals {
    top: calc(82px + var(--safe-top));
    left: calc(12px + var(--safe-left));
    width: 128px;
    gap: 5px;
    padding: 7px 8px;
  }
  .vital { gap: 5px; }
  .vital-label { width: 34px; font-size: 5.5px; letter-spacing: .1em; }
  .bar { height: 4px; }

  .minimap-wrap {
    top: calc(82px + var(--safe-top));
    right: calc(12px + var(--safe-right));
    width: 106px;
    padding: 3px 3px 2px;
  }
  #minimap { width: 98px; height: 73px; }
  .minimap-label { font-size: 5px; padding-top: 2px; letter-spacing: .14em; }

  .resources {
    left: calc(12px + var(--safe-left));
    top: calc(164px + var(--safe-top));
    bottom: auto;
    max-width: 170px;
