function drawWeather(ctx, game, t, w, h) {
  if (game.weather.type === 'rain' && game.mode !== 'title') {
    ctx.save();
    ctx.strokeStyle = 'rgba(170, 195, 200, 0.19)';
    ctx.lineWidth = 1;
