    }
    g.camera.x = g.player.x; g.camera.y = g.player.y;
  });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `/tmp/opencode/shots/adapt-enemies-${name}.png` });
  console.log(name, 'errors', errors);
  await page.close();
}
await browser.close();
